insert into abril_trainer_exercises (id, owner_id, name, primary_muscle, secondary_muscles, equipment, difficulty, media_url, steps) values
  ('EIeI8Vf', null, 'Press de banca con barra', 'chest', array['triceps']::text[], 'Barra', 'Intermedio', 'catalog/EIeI8Vf.mp4', array['Túmbate en el banco con los pies apoyados en el suelo y la espalda pegada al banco.', 'Agarra la barra en pronación algo más abierto que la anchura de los hombros.', 'Saca la barra del soporte y sujétala justo encima del pecho con los brazos estirados del todo.', 'Baja la barra despacio hacia el pecho, con los codos recogidos.', 'Aguanta un momento cuando la barra toque el pecho.']::text[]),
  ('SpYC0Kp', null, 'Press de banca con mancuernas', 'chest', array['triceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/SpYC0Kp.mp4', array['Túmbate en el banco con los pies apoyados en el suelo y la espalda pegada al banco.', 'Sujeta una mancuerna en cada mano, con las palmas hacia delante y los brazos estirados encima del pecho.', 'Baja las mancuernas despacio a los lados del pecho, con los codos a 90 grados.', 'Aguanta un momento y empuja las mancuernas de vuelta a la posición inicial, estirando los brazos del todo.', 'Repite las repeticiones que quieras.']::text[]),
  ('3TZduzM', null, 'Press inclinado con barra', 'chest', array['triceps']::text[], 'Barra', 'Intermedio', 'catalog/3TZduzM.mp4', array['Coloca un banco inclinado a 45 grados.', 'Túmbate en el banco con los pies apoyados en el suelo.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Saca la barra del soporte y bájala despacio hacia el pecho, con los codos a unos 45 grados.', 'Aguanta un momento abajo y empuja la barra de vuelta a la posición inicial.']::text[]),
  ('ns0SIbU', null, 'Press inclinado con mancuernas', 'chest', array['triceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/ns0SIbU.mp4', array['Coloca un banco inclinado a 45 grados.', 'Siéntate en el banco con los pies apoyados en el suelo y la espalda bien pegada al respaldo.', 'Sujeta una mancuerna en cada mano con las palmas hacia delante y súbelas a la altura de los hombros.', 'Baja las mancuernas despacio a los lados del pecho, con los codos a 90 grados.', 'Empuja las mancuernas de vuelta a la posición inicial estirando los brazos del todo.']::text[]),
  ('GrO65fd', null, 'Press declinado con barra', 'chest', array['triceps']::text[], 'Barra', 'Intermedio', 'catalog/GrO65fd.mp4', array['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que la cadera.', 'Agarra la barra en pronación algo más abierto que la anchura de los hombros.', 'Saca la barra del soporte y bájala despacio hacia el pecho, con los codos recogidos.', 'Aguanta un momento abajo y empuja la barra de vuelta a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('yz9nUhF', null, 'Aperturas con mancuernas', 'chest', '{}', 'Mancuernas', 'Principiante', 'catalog/yz9nUhF.mp4', array['Túmbate en un banco con una mancuerna en cada mano y las palmas enfrentadas.', 'Estira los brazos hacia arriba encima del pecho, con los codos algo flexionados.', 'Con los codos algo flexionados, baja los brazos a los lados en un arco amplio hasta notar el estiramiento en el pecho.', 'Aguanta un momento, invierte el movimiento y sube las mancuernas a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('I4hDWkc', null, 'Flexiones', 'chest', array['triceps']::text[], 'Peso corporal', 'Intermedio', 'catalog/I4hDWkc.mp4', array['Empieza en plancha alta con las manos algo más abiertas que los hombros y los pies juntos.', 'Aprieta el core y baja el cuerpo hacia el suelo flexionando los codos, manteniéndote en línea recta.', 'Aguanta un momento con el pecho justo encima del suelo y empuja para volver a la posición inicial estirando los brazos.', 'Repite las repeticiones que quieras.']::text[]),
  ('9WTm7dq', null, 'Fondos en paralelas para pecho', 'chest', array['triceps']::text[], 'Peso corporal', 'Intermedio', 'catalog/9WTm7dq.mp4', array['Colócate en las paralelas con los brazos estirados del todo y el cuerpo recto.', 'Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de ellos.', 'Empuja para volver a la posición inicial estirando los brazos.', 'Repite las repeticiones que quieras.']::text[]),
  ('9XjtHvS', null, 'Pullover con mancuerna', 'chest', array['triceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/9XjtHvS.mp4', array['Túmbate en el banco con la cabeza en un extremo y los pies en el suelo.', 'Sujeta una mancuerna con las dos manos y estira los brazos encima del pecho.', 'Con los codos algo flexionados, baja la mancuerna despacio por detrás de la cabeza hasta notar el estiramiento en pecho y hombros.', 'Aguanta un momento y sube la mancuerna a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('Kyd9Rz5', null, 'Press militar de pie con barra y agarre ancho', 'shoulders', array['triceps', 'back']::text[], 'Barra', 'Intermedio', 'catalog/Kyd9Rz5.mp4', array['Ponte de pie con los pies a la anchura de los hombros y sujeta la barra en pronación, algo más abierto que los hombros.', 'Sube la barra a la altura de los hombros, con los codos algo por delante de ella.', 'Empuja la barra por encima de la cabeza estirando los brazos del todo.', 'Baja la barra a la altura de los hombros y repite las repeticiones que quieras.']::text[]),
  ('A6wtbuL', null, 'Press militar de pie con mancuernas', 'shoulders', array['triceps', 'back']::text[], 'Mancuernas', 'Intermedio', 'catalog/A6wtbuL.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano a la altura de los hombros, con las palmas hacia delante.', 'Empuja las mancuernas hacia arriba hasta estirar los brazos del todo sobre la cabeza.', 'Aguanta un momento arriba y baja las mancuernas despacio a la altura de los hombros.', 'Repite las repeticiones que quieras.']::text[]),
  ('Xy4jlWA', null, 'Press Arnold con mancuernas', 'shoulders', array['triceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/Xy4jlWA.mp4', array['Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura de los hombros, con las palmas hacia ti y los codos flexionados.', 'Empuja las mancuernas hacia arriba hasta estirar los brazos del todo, con las palmas hacia delante.', 'Gira las muñecas mientras subes, de modo que arriba las palmas miren hacia delante.', 'Aguanta un momento arriba y baja las mancuernas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('DsgkuIt', null, 'Elevaciones laterales con mancuernas', 'shoulders', array['trapezius']::text[], 'Mancuernas', 'Principiante', 'catalog/DsgkuIt.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano, con las palmas hacia ti.', 'Mantén la espalda recta y aprieta el core.', 'Sube los brazos a los lados hasta dejarlos paralelos al suelo, con los codos algo flexionados.', 'Aguanta un momento arriba y baja los brazos despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('goJ6ezq', null, 'Elevaciones laterales en polea', 'shoulders', array['trapezius', 'triceps']::text[], 'Polea', 'Principiante', 'catalog/goJ6ezq.mp4', array['Ponte de pie con los pies a la anchura de los hombros y agarra las asas de la polea en pronación.', 'Mantén los brazos estirados y el core apretado.', 'Sube los brazos a los lados hasta dejarlos paralelos al suelo.', 'Aguanta un momento arriba y baja los brazos despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('3eGE2JC', null, 'Elevaciones frontales con mancuernas', 'shoulders', array['biceps']::text[], 'Mancuernas', 'Principiante', 'catalog/3eGE2JC.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano, con las palmas mirando a los muslos.', 'Con los brazos estirados, suelta el aire y sube las mancuernas por delante hasta la altura de los hombros.', 'Aguanta un momento arriba, coge aire y baja las mancuernas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('v1qBec9', null, 'Pájaros con mancuernas', 'shoulders', array['trapezius']::text[], 'Mancuernas', 'Principiante', 'catalog/v1qBec9.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano, con las palmas hacia ti.', 'Flexiona un poco las rodillas e inclínate desde la cadera, con la espalda recta y el core apretado.', 'Sube los brazos a los lados, con los codos algo flexionados, hasta dejarlos paralelos al suelo.', 'Aguanta un momento arriba y baja los brazos despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('NJzBsGJ', null, 'Encogimientos con mancuernas', 'trapezius', '{}', 'Mancuernas', 'Principiante', 'catalog/NJzBsGJ.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano, con las palmas hacia el cuerpo.', 'Mantén los brazos estirados y deja las mancuernas colgando a los lados.', 'Sube los hombros todo lo que puedas, como si quisieras tocarte las orejas con ellos.', 'Aguanta la contracción un segundo y baja los hombros despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('dG7tG5y', null, 'Encogimientos con barra', 'trapezius', '{}', 'Barra', 'Principiante', 'catalog/dG7tG5y.mp4', array['Ponte de pie con los pies a la anchura de los hombros y sujeta la barra delante de ti en pronación.', 'Mantén los brazos y la espalda rectos durante todo el ejercicio.', 'Sube los hombros hacia las orejas todo lo que puedas, apretando el trapecio arriba.', 'Aguanta un momento y baja los hombros despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('ila4NZS', null, 'Peso muerto con barra', 'glutes', array['hamstrings']::text[], 'Barra', 'Avanzado', 'catalog/ila4NZS.mp4', array['Ponte de pie con los pies a la anchura de los hombros y la barra en el suelo delante de ti.', 'Flexiona las rodillas e inclínate desde la cadera para bajar el tronco y agarrar la barra en pronación, con las manos algo más abiertas que los hombros.', 'Mantén la espalda recta y el pecho alto mientras empujas con los talones para despegar la barra del suelo, estirando cadera y rodillas.', 'Al terminar de pie, aprieta los glúteos y mantén el core activo.', 'Baja la barra al suelo flexionando cadera y rodillas, con la espalda recta.']::text[]),
  ('wQ2c4XD', null, 'Peso muerto rumano con barra', 'glutes', array['hamstrings']::text[], 'Barra', 'Avanzado', 'catalog/wQ2c4XD.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas hacia delante.', 'Sujeta la barra en pronación, con las manos algo más abiertas que los hombros.', 'Inclínate desde la cadera, con la espalda recta y las rodillas algo flexionadas.', 'Baja la barra hacia el suelo, manteniéndola pegada al cuerpo.', 'Nota el estiramiento en los isquios mientras bajas la barra.']::text[]),
  ('KgI0tqW', null, 'Peso muerto sumo con barra', 'glutes', array['hamstrings']::text[], 'Barra', 'Avanzado', 'catalog/KgI0tqW.mp4', array['Ponte de pie con los pies más abiertos que los hombros y las puntas hacia fuera.', 'Coloca la barra en el suelo delante de ti, centrada entre los pies.', 'Flexiona las rodillas y baja la cadera, con la espalda recta y el pecho alto, para agarrar la barra en pronación.', 'Aprieta el core y empuja con los talones para despegar la barra del suelo, estirando cadera y rodillas a la vez.', 'Mientras subes, mantén el pecho alto y la espalda recta, y empuja la cadera hacia delante para activar bien los glúteos.']::text[]),
  ('eZyBC3j', null, 'Remo con barra', 'back', array['biceps', 'forearm']::text[], 'Barra', 'Intermedio', 'catalog/eZyBC3j.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las rodillas algo flexionadas.', 'Inclínate hacia delante desde la cadera, con la espalda recta y el pecho alto.', 'Agarra la barra en pronación, con las manos algo más abiertas que los hombros.', 'Tira de la barra hacia la parte baja del pecho llevando las escápulas atrás y apretando la espalda.', 'Aguanta un momento arriba y baja la barra despacio a la posición inicial.']::text[]),
  ('BJ0Hz5L', null, 'Remo con mancuernas', 'back', array['biceps', 'forearm']::text[], 'Mancuernas', 'Intermedio', 'catalog/BJ0Hz5L.mp4', array['Ponte de pie con los pies a la anchura de los hombros, las rodillas algo flexionadas y una mancuerna en cada mano, con las palmas hacia el cuerpo.', 'Inclínate hacia delante desde la cadera, con la espalda recta y el core apretado.', 'Deja los brazos colgando hacia el suelo, con los codos algo flexionados.', 'Sube las mancuernas hacia el pecho juntando las escápulas.', 'Aguanta un momento arriba y baja las mancuernas despacio a la posición inicial.']::text[]),
  ('r0z6xzQ', null, 'Remo Pendlay con barra', 'back', array['biceps', 'forearm']::text[], 'Barra', 'Intermedio', 'catalog/r0z6xzQ.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las rodillas algo flexionadas.', 'Inclínate desde la cadera, con la espalda recta y el pecho alto.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Tira de la barra hacia la parte alta del abdomen juntando las escápulas.', 'Baja la barra a la posición inicial.']::text[]),
  ('fUBheHs', null, 'Remo sentado en polea', 'back', array['biceps', 'forearm']::text[], 'Polea', 'Principiante', 'catalog/fUBheHs.mp4', array['Siéntate en la máquina de remo con los pies apoyados en los reposapiés y las rodillas algo flexionadas.', 'Agarra las asas en pronación, con la espalda recta y los hombros relajados.', 'Tira de las agarraderas hacia el cuerpo juntando las escápulas.', 'Aguanta un momento en el punto máximo y suelta las agarraderas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('RVwzP10', null, 'Jalón al pecho en polea', 'back', array['biceps', 'forearm']::text[], 'Polea', 'Principiante', 'catalog/RVwzP10.mp4', array['Ajusta la máquina de jalón para que el asiento quede a una altura cómoda y la almohadilla te sujete las rodillas.', 'Siéntate con la espalda recta y los pies apoyados en el suelo.', 'Agarra la barra de la polea en pronación, algo más abierto que la anchura de los hombros.', 'Échate un poco hacia atrás y aprieta el core.', 'Tira de la barra hacia el pecho juntando las escápulas.']::text[]),
  ('lBDjFxJ', null, 'Dominadas', 'back', array['biceps', 'forearm']::text[], 'Peso corporal', 'Intermedio', 'catalog/lBDjFxJ.mp4', array['Cuélgate de la barra en pronación, con los brazos estirados del todo.', 'Aprieta el core y junta las escápulas.', 'Sube el cuerpo hacia la barra flexionando los codos y llevando el pecho hacia ella.', 'Aguanta arriba y baja el cuerpo despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('T2mxWqc', null, 'Dominadas supinas', 'back', array['biceps', 'forearm']::text[], 'Peso corporal', 'Intermedio', 'catalog/T2mxWqc.mp4', array['Cuélgate de la barra en supinación, con las manos a la anchura de los hombros.', 'Aprieta el core y sube el cuerpo hacia la barra, llevando el pecho por delante.', 'Sigue tirando hasta pasar la barbilla por encima de la barra.', 'Aguanta un momento arriba y baja el cuerpo despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('EAs3xL9', null, 'Pájaros invertidos con mancuernas', 'shoulders', '{}', 'Mancuernas', 'Principiante', 'catalog/EAs3xL9.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano.', 'Flexiona un poco las rodillas e inclínate hacia delante desde la cadera, con la espalda recta.', 'Estira los brazos hacia abajo por delante, con las palmas enfrentadas.', 'Con los codos algo flexionados, sube los brazos a los lados hasta dejarlos paralelos al suelo.', 'Aguanta un momento arriba y baja los brazos despacio a la posición inicial.']::text[]),
  ('qXTaZnJ', null, 'Sentadilla completa con barra', 'glutes', array['hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/qXTaZnJ.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Apoya la barra en la parte alta de la espalda, sobre el trapecio o el deltoides posterior.', 'Aprieta el core y mantén el pecho alto mientras empiezas a bajar.', 'Flexiona rodillas y cadera, llevando la cadera atrás y abajo como si fueras a sentarte.', 'Baja hasta que los muslos queden paralelos al suelo o algo por debajo.']::text[]),
  ('zG0zs85', null, 'Sentadilla frontal con barra', 'glutes', array['hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/zG0zs85.mp4', array['Empieza de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Sujeta la barra delante de los hombros, apoyada en la clavícula y los deltoides.', 'Aprieta el core y mantén el pecho alto mientras bajas a la sentadilla, llevando la cadera atrás y flexionando las rodillas.', 'Baja hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.', 'Aguanta un momento abajo y empuja con los talones para volver a la posición inicial.']::text[]),
  ('yn8yg1r', null, 'Sentadilla goblet con mancuerna', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Mancuernas', 'Intermedio', 'catalog/yn8yg1r.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en vertical contra el pecho, sujeta con las dos manos.', 'Con el pecho alto y el core apretado, baja a la sentadilla llevando la cadera atrás y flexionando las rodillas.', 'Sigue bajando hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.', 'Aguanta un momento abajo y empuja con los talones para volver a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('7zdxRTl', null, 'Prensa de piernas en multipower', 'glutes', array['hamstrings', 'calves']::text[], 'Máquina', 'Principiante', 'catalog/7zdxRTl.mp4', array['Ajusta el asiento y la plataforma del multipower a una posición cómoda.', 'Siéntate en la máquina con la espalda contra el respaldo y los pies a la anchura de los hombros en la plataforma.', 'Agárrate a las asas o a los lados de la máquina para estabilizarte.', 'Empuja la plataforma estirando las piernas, con la espalda pegada al respaldo.', 'Aguanta un momento con las piernas estiradas del todo.']::text[]),
  ('RRWFUcw', null, 'Zancadas con mancuernas', 'glutes', array['hamstrings', 'calves']::text[], 'Mancuernas', 'Intermedio', 'catalog/RRWFUcw.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano.', 'Da un paso adelante con el pie derecho y baja a la zancada.', 'Mantén la espalda recta y el pecho alto mientras bajas.', 'Empuja con el talón derecho para volver a la posición inicial.', 'Repite con la pierna izquierda.']::text[]),
  ('qx4fgX7', null, 'Sentadilla búlgara a una pierna con mancuernas', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Mancuernas', 'Intermedio', 'catalog/qx4fgX7.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano.', 'Da un paso adelante con un pie y colócate de modo que el pie de delante quede plano en el suelo y el de atrás elevado sobre un banco o step.', 'Baja el cuerpo flexionando la rodilla y la cadera de delante, con la rodilla de atrás algo flexionada y el talón despegado.', 'Sigue bajando hasta que el muslo de delante quede paralelo al suelo y empuja con ese talón para volver a la posición inicial.', 'Repite las repeticiones que quieras y cambia de pierna.']::text[]),
  ('XlZ4lAC', null, 'Buenos días con barra', 'hamstrings', '{}', 'Barra', 'Intermedio', 'catalog/XlZ4lAC.mp4', array['Empieza de pie con los pies a la anchura de los hombros y la barra apoyada en la parte alta de la espalda.', 'Con la espalda recta y el core apretado, inclínate desde la cadera llevando el culo atrás, como si quisieras tocar la pared de detrás con los glúteos.', 'Baja el tronco hasta dejarlo paralelo al suelo, notando el estiramiento en los isquios.', 'Aguanta un momento y vuelve a la posición inicial apretando los glúteos y empujando la cadera hacia delante.', 'Repite las repeticiones que quieras.']::text[]),
  ('qKBpF7I', null, 'Puente de glúteo con barra', 'glutes', array['hamstrings']::text[], 'Barra', 'Intermedio', 'catalog/qKBpF7I.mp4', array['Empieza tumbado boca arriba en el suelo, con las rodillas flexionadas y los pies apoyados.', 'Coloca una barra sobre la cadera y sujétala firme con las dos manos.', 'Aprieta glúteos y core y despega la cadera del suelo hasta dejar el cuerpo en línea recta de las rodillas a los hombros.', 'Aguanta un momento arriba apretando los glúteos.', 'Baja la cadera despacio a la posición inicial.']::text[]),
  ('OM46QHm', null, 'Pull through en polea con cuerda', 'glutes', array['hamstrings']::text[], 'Polea', 'Principiante', 'catalog/OM46QHm.mp4', array['Ponte de pie de espaldas a la polea con los pies a la anchura de los hombros.', 'Agarra la cuerda con las dos manos y da un paso adelante para tensar el cable.', 'Inclínate desde la cadera y baja el tronco hasta dejarlo paralelo al suelo, con la espalda recta.', 'Aprieta glúteos e isquios para subir el cuerpo a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('8ozhUIZ', null, 'Elevación de gemelos de pie con barra', 'calves', array['hamstrings', 'glutes']::text[], 'Barra', 'Principiante', 'catalog/8ozhUIZ.mp4', array['Ponte de pie con los pies a la anchura de los hombros y apoya la barra en la parte alta de la espalda.', 'Despega los talones del suelo todo lo que puedas, apoyándote solo en las puntas.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('ktsFQAZ', null, 'Elevación de gemelos sentado con barra', 'calves', array['hamstrings']::text[], 'Barra', 'Principiante', 'catalog/ktsFQAZ.mp4', array['Siéntate en un banco con los pies apoyados en el suelo y una barra sobre los muslos.', 'Apoya la punta de los pies en una plataforma elevada, como un taco o un step.', 'Coloca la barra sobre los muslos y sujétala firme con las manos.', 'Con la espalda recta y el core apretado, despega los talones del suelo estirando los tobillos.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.']::text[]),
  ('Y1MsI1l', null, 'Extensión de cuádriceps con goma', 'quads', array['hamstrings']::text[], 'Banda elástica', 'Principiante', 'catalog/Y1MsI1l.mp4', array['Engancha la goma a un punto fijo resistente y pásatela por el tobillo.', 'Ponte de pie frente al anclaje con los pies a la anchura de los hombros.', 'Con el core apretado y el tronco estable, estira la pierna hacia delante.', 'Aguanta un momento arriba y devuelve la pierna despacio a la posición inicial.', 'Repite las repeticiones que quieras y cambia de pierna.']::text[]),
  ('zHEpuuc', null, 'Curl femoral inverso asistido en polea', 'hamstrings', array['glutes', 'calves']::text[], 'Polea', 'Principiante', 'catalog/zHEpuuc.mp4', array['Ajusta la polea con la tobillera en la posición más baja.', 'Túmbate boca abajo en el banco con las piernas estiradas y la tobillera sujeta.', 'Agárrate a las asas del banco para estabilizarte.', 'Con el tronco quieto, suelta el aire y lleva las piernas hacia los glúteos flexionando las rodillas.', 'Aguanta un momento arriba apretando los isquios.']::text[]),
  ('25GPyDY', null, 'Curl de bíceps con barra', 'biceps', array['forearm']::text[], 'Barra', 'Principiante', 'catalog/25GPyDY.mp4', array['Ponte de pie con los pies a la anchura de los hombros y sujeta la barra en supinación, con las palmas hacia delante.', 'Mantén los codos pegados al cuerpo y suelta el aire mientras subes el peso contrayendo el bíceps.', 'Sigue subiendo la barra hasta contraer el bíceps del todo, con la barra a la altura de los hombros.', 'Aguanta un instante en la contracción apretando el bíceps.', 'Coge aire mientras bajas la barra despacio a la posición inicial.']::text[]),
  ('NbVPDMW', null, 'Curl de bíceps con mancuernas', 'biceps', array['forearm']::text[], 'Mancuernas', 'Principiante', 'catalog/NbVPDMW.mp4', array['Ponte de pie con una mancuerna en cada mano, las palmas hacia delante y los brazos estirados del todo.', 'Con los brazos quietos, suelta el aire y sube el peso contrayendo el bíceps.', 'Sigue subiendo el peso hasta contraer el bíceps del todo, con las mancuernas a la altura de los hombros.', 'Aguanta un instante en la contracción apretando el bíceps.', 'Coge aire y empieza a bajar las mancuernas despacio a la posición inicial.']::text[]),
  ('slDvUAU', null, 'Curl martillo con mancuernas', 'biceps', array['forearm']::text[], 'Mancuernas', 'Principiante', 'catalog/slDvUAU.mp4', array['Ponte de pie con una mancuerna en cada mano y las palmas mirando al cuerpo.', 'Mantén los codos pegados al cuerpo y gira las palmas hasta que miren hacia delante.', 'Esa es la posición inicial.', 'Ahora, con los brazos quietos, suelta el aire y sube el peso contrayendo el bíceps.', 'Sigue subiendo el peso hasta contraer el bíceps del todo, con las mancuernas a la altura de los hombros.']::text[]),
  ('qOgPVf6', null, 'Curl predicador con barra', 'biceps', array['forearm']::text[], 'Barra', 'Principiante', 'catalog/qOgPVf6.mp4', array['Siéntate en el banco predicador con los brazos apoyados en la almohadilla y el pecho contra el soporte.', 'Agarra la barra en supinación, algo más abierto que la anchura de los hombros.', 'Con los brazos quietos, suelta el aire y sube la barra hacia los hombros.', 'Aguanta un momento arriba apretando el bíceps.', 'Coge aire y baja la barra despacio a la posición inicial.']::text[]),
  ('gvsWLQw', null, 'Curl concentrado con mancuerna', 'biceps', array['forearm']::text[], 'Mancuernas', 'Principiante', 'catalog/gvsWLQw.mp4', array['Siéntate en un banco con las piernas abiertas y una mancuerna en una mano, apoyando el codo en la cara interna del muslo.', 'Estira el brazo del todo y sujeta la mancuerna en supinación.', 'Con el brazo quieto, suelta el aire y sube el peso hacia el hombro contrayendo el bíceps.', 'Sigue subiendo la mancuerna hasta contraer el bíceps del todo, con la mancuerna a la altura del hombro.', 'Aguanta un instante en la contracción apretando el bíceps.']::text[]),
  ('3ZflifB', null, 'Extensión de tríceps en polea', 'triceps', array['forearm']::text[], 'Polea', 'Principiante', 'catalog/3ZflifB.mp4', array['Engancha una barra recta a una polea alta.', 'Ponte de pie frente a la máquina con los pies a la anchura de los hombros y las rodillas algo flexionadas.', 'Agarra la barra en pronación, con las manos a la anchura de los hombros.', 'Mantén los codos pegados al cuerpo y los brazos quietos.', 'Suelta el aire y empuja la barra hacia abajo hasta estirar los codos del todo.']::text[]),
  ('iZop9xO', null, 'Press francés tumbado con barra', 'triceps', '{}', 'Barra', 'Principiante', 'catalog/iZop9xO.mp4', array['Túmbate en el banco con los pies apoyados en el suelo y la cabeza al final del banco.', 'Sujeta la barra en pronación, con las manos a la anchura de los hombros, y estira los brazos encima del pecho.', 'Con los brazos quietos, baja la barra despacio hacia la frente flexionando los codos.', 'Aguanta un momento abajo y estira los brazos de vuelta a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('PdmaD0N', null, 'Extensión de tríceps de pie con mancuerna', 'triceps', '{}', 'Mancuernas', 'Principiante', 'catalog/PdmaD0N.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en una mano.', 'Sube la mancuerna por encima de la cabeza con el brazo estirado.', 'Flexiona el codo y baja la mancuerna por detrás de la cabeza, con el brazo quieto.', 'Estira el brazo de vuelta a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('2IxROQ1', null, 'Extensión de tríceps sobre la cabeza en polea con cuerda', 'triceps', '{}', 'Polea', 'Principiante', 'catalog/2IxROQ1.mp4', array['Engancha una cuerda a la polea en posición alta.', 'Ponte de pie de espaldas a la máquina con los pies a la anchura de los hombros.', 'Agarra la cuerda con las dos manos, palmas enfrentadas, y llévalas por encima de la cabeza.', 'Mantén los brazos pegados a la cabeza y los codos apuntando hacia delante.', 'Baja la cuerda despacio por detrás de la cabeza flexionando los codos.']::text[]),
  ('X6C6i5Y', null, 'Fondos en paralelas para tríceps', 'triceps', '{}', 'Peso corporal', 'Intermedio', 'catalog/X6C6i5Y.mp4', array['Siéntate en el borde de un banco o una silla agarrando el borde, con los dedos hacia delante.', 'Desliza el culo fuera del banco y aguanta el peso con las manos.', 'Flexiona los codos y baja el cuerpo hacia el suelo, con la espalda pegada al banco.', 'Aguanta un momento abajo y empuja para volver a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('VBAWRPG', null, 'Plancha frontal con lastre', 'abdomen', '{}', 'Con lastre', 'Intermedio', 'catalog/VBAWRPG.mp4', array['Empieza tumbado boca abajo en el suelo.', 'Apoya los antebrazos en el suelo, con los codos justo debajo de los hombros.', 'Estira las piernas hacia atrás, apoyando las puntas de los pies.', 'Aprieta el core y despega el cuerpo del suelo, apoyado en antebrazos y puntas.', 'Mantén el cuerpo en línea recta de la cabeza a los talones.']::text[]),
  ('TFqbd8t', null, 'Crunch en el suelo', 'abdomen', '{}', 'Peso corporal', 'Principiante', 'catalog/TFqbd8t.mp4', array['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Pon las manos detrás de la cabeza con los codos abiertos.', 'Aprieta el abdomen y despega los hombros del suelo, enrollándote hacia las rodillas.', 'Aguanta un momento arriba y baja los hombros despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('jpgqxiS', null, 'Crunch de pie en polea', 'abdomen', array['obliques']::text[], 'Polea', 'Principiante', 'catalog/jpgqxiS.mp4', array['Engancha un asa a la polea alta y ponte de espaldas a la máquina.', 'Sujeta el asa con las dos manos y colócala detrás de la cabeza, con los codos flexionados.', 'Ponte de pie con los pies a la anchura de los hombros y las rodillas algo flexionadas.', 'Con el abdomen apretado, suelta el aire y lleva el tronco hacia las rodillas, acercando los codos a los muslos.', 'Aguanta un momento abajo y vuelve despacio a la posición inicial.']::text[]),
  ('QOA0FD0', null, 'Elevación de piernas colgado con lastre', 'abdomen', '{}', 'Con lastre', 'Principiante', 'catalog/QOA0FD0.mp4', array['Cuélgate de la barra en pronación, con los brazos estirados del todo.', 'Aprieta el core y sube las piernas por delante, manteniéndolas estiradas.', 'Sigue subiendo hasta que las piernas queden paralelas al suelo o algo por encima.', 'Aguanta un momento arriba y baja las piernas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('XVDdcoj', null, 'Giro ruso', 'abdomen', array['obliques']::text[], 'Peso corporal', 'Intermedio', 'catalog/XVDdcoj.mp4', array['Siéntate en el suelo con las rodillas flexionadas y los pies apoyados.', 'Échate un poco hacia atrás manteniendo la espalda recta y el core apretado.', 'Junta las manos delante del pecho, o sujeta un peso si quieres.', 'Despega los pies del suelo, en equilibrio sobre los isquiones.', 'Gira el tronco a la derecha, llevando las manos o el peso hacia ese lado.']::text[]),
  ('cA9FuWG', null, 'Pullover con barra y brazos flexionados', 'back', array['triceps']::text[], 'Barra', 'Intermedio', 'catalog/cA9FuWG.mp4', array['Túmbate en el banco con la cabeza en un extremo y los pies en el suelo.', 'Sujeta una barra con las manos a la anchura de los hombros y estira los brazos encima del pecho.', 'Baja la barra por detrás de la cabeza con los brazos algo flexionados.', 'Aguanta un momento y sube la barra de vuelta a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('7vG5o25', null, 'Remo inclinado con mancuernas', 'back', array['biceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/7vG5o25.mp4', array['Coloca un banco inclinado a 45 grados.', 'Coge una mancuerna en cada mano y siéntate en el banco con el pecho contra el respaldo inclinado.', 'Estira los brazos del todo, dejando las mancuernas colgando desde los hombros.', 'Sube las mancuernas hacia el pecho juntando las escápulas.', 'Aguanta un momento arriba y baja las mancuernas despacio a la posición inicial.']::text[]),
  ('4IKbhHV', null, 'Jalón lateral alterno', 'back', array['biceps']::text[], 'Polea', 'Principiante', 'catalog/4IKbhHV.mp4', array['Siéntate en la máquina de polea con la espalda recta y los pies apoyados en el suelo.', 'Agarra las agarraderas en pronación, algo más abierto que la anchura de los hombros.', 'Échate un poco atrás y tira de las asas hacia el pecho juntando las escápulas.', 'Aguanta un momento en el punto máximo y suelta las agarraderas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('vrhHa6D', null, 'Dominadas asistidas en paralelas con agarre cerrado', 'back', array['biceps', 'forearm']::text[], 'Máquina', 'Principiante', 'catalog/vrhHa6D.mp4', array['Ajusta la máquina al peso y la altura que quieras.', 'Pon las manos en las paralelas con agarre cerrado y las palmas enfrentadas.', 'Cuélgate de las barras con los brazos estirados del todo y los pies en el aire.', 'Aprieta la espalda y sube el cuerpo hacia las barras, con los codos pegados al cuerpo.', 'Sigue tirando hasta pasar la barbilla por encima de las barras.']::text[]),
  ('72BC5Za', null, 'Dominadas de arquero', 'back', array['biceps', 'forearm']::text[], 'Peso corporal', 'Intermedio', 'catalog/72BC5Za.mp4', array['Empieza colgado de la barra en pronación, algo más abierto que la anchura de los hombros.', 'Aprieta el core y lleva las escápulas abajo y atrás.', 'Al subir, flexiona un brazo llevando el codo al costado mientras mantienes el otro estirado.', 'Sigue tirando hasta pasar la barbilla por encima de la barra con el brazo flexionado del todo.', 'Baja controlando, estira el brazo flexionado y repite hacia el otro lado.']::text[]),
  ('Gk1r408', null, 'Dominadas supinas con agarre cerrado y lastre', 'back', array['biceps', 'forearm']::text[], 'Con lastre', 'Intermedio', 'catalog/Gk1r408.mp4', array['Ponte delante de la jaula y agarra las paralelas en supinación, con las manos a la anchura de los hombros.', 'Cuélgate de las barras con los brazos estirados del todo, los pies en el aire y el cuerpo recto.', 'Aprieta la espalda y sube el cuerpo hacia las barras, con los codos pegados a los costados.', 'Sigue tirando hasta pasar la barbilla por encima de las barras y aguanta un momento.', 'Baja el cuerpo despacio a la posición inicial, estirando los brazos del todo.']::text[]),
  ('hMEptv0', null, 'Pullover declinado con barra y brazos flexionados', 'back', array['triceps']::text[], 'Barra', 'Intermedio', 'catalog/hMEptv0.mp4', array['Túmbate en un banco declinado con la cabeza más baja que la cadera y los pies sujetos.', 'Sujeta la barra en pronación (palmas hacia fuera) y estira los brazos encima del pecho.', 'Baja la barra por detrás de la cabeza de forma controlada, con los brazos algo flexionados.', 'Aguanta un momento y sube la barra a la posición inicial contrayendo los dorsales.', 'Repite las repeticiones que quieras.']::text[]),
  ('PbzNu7c', null, 'Elevación en Y inclinada con mancuernas', 'back', '{}', 'Mancuernas', 'Principiante', 'catalog/PbzNu7c.mp4', array['Pon un banco inclinado a 45 grados y siéntate con una mancuerna en cada mano, palmas hacia dentro.', 'Inclínate un poco hacia delante y deja los brazos colgando, con los codos algo flexionados.', 'Sube los brazos a los lados formando una Y hasta dejarlos paralelos al suelo.', 'Aguanta un momento arriba y baja los brazos despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('eYnzaCm', null, 'Jalón lateral con barra en polea', 'back', array['biceps']::text[], 'Polea', 'Principiante', 'catalog/eYnzaCm.mp4', array['Pon la polea en posición alta y engancha una barra recta.', 'Siéntate frente a la polea con los pies apoyados en el suelo y las rodillas algo flexionadas.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Échate un poco atrás con el pecho alto, manteniendo una ligera curva lumbar.', 'Tira de la barra hacia el pecho llevando los codos por delante y juntando las escápulas.']::text[]),
  ('kiJ4Z2K', null, 'Dominadas asistidas', 'back', array['biceps', 'forearm']::text[], 'Máquina', 'Principiante', 'catalog/kiJ4Z2K.mp4', array['Ajusta la máquina al peso y la altura que quieras.', 'Agarra las agarraderas en pronación, algo más abierto que la anchura de los hombros.', 'Cuélgate con los brazos estirados del todo y los pies en el aire.', 'Aprieta la espalda y sube el cuerpo hacia las asas, con los codos pegados al cuerpo.', 'Sigue tirando hasta pasar la barbilla por encima de las asas.']::text[]),
  ('GaSzzuh', null, 'Back lever', 'back', array['biceps', 'forearm']::text[], 'Peso corporal', 'Intermedio', 'catalog/GaSzzuh.mp4', array['Empieza colgado de la barra en pronación, con las manos algo más abiertas que los hombros.', 'Aprieta el core y lleva las escápulas abajo y atrás.', 'Flexiona las rodillas y llévalas al pecho.', 'Sube las piernas despacio, estiradas, hasta dejar el cuerpo paralelo al suelo.', 'Aguanta esa posición unos segundos y baja las piernas despacio a la posición inicial.']::text[]),
  ('8urJS9b', null, 'Hiperextensiones con lastre en fitball', 'back', array['glutes', 'hamstrings']::text[], 'Con lastre', 'Principiante', 'catalog/8urJS9b.mp4', array['Colócate boca abajo sobre un fitball con la cadera apoyada en él y los pies contra una pared para estabilizarte.', 'Pon las manos detrás de la cabeza o crúzalas sobre el pecho.', 'Aprieta el core y despega el tronco del balón despacio, extendiendo la espalda hasta quedar en línea recta.', 'Aguanta un momento arriba y baja el tronco despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('Hj4FOCd', null, 'Pullover declinado con barra y agarre ancho', 'back', array['triceps']::text[], 'Barra', 'Intermedio', 'catalog/Hj4FOCd.mp4', array['Túmbate en un banco declinado con la cabeza más baja que la cadera y los pies sujetos.', 'Sujeta la barra con agarre ancho y estira los brazos encima del pecho.', 'Baja la barra por detrás de la cabeza de forma controlada, con los brazos estirados.', 'Aguanta un momento y sube la barra de vuelta a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('XUUD0Fs', null, 'Remo posterior tumbado con mancuernas', 'back', array['biceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/XUUD0Fs.mp4', array['Túmbate boca abajo en un banco plano con una mancuerna en cada mano, palmas hacia dentro.', 'Estira los brazos hacia el suelo, con los codos algo flexionados.', 'Apretando la espalda, sube las mancuernas hacia el pecho juntando las escápulas.', 'Aguanta un momento arriba y baja las mancuernas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('OQ1otBN', null, 'Jalón lateral cruzado en polea', 'back', array['biceps']::text[], 'Polea', 'Principiante', 'catalog/OQ1otBN.mp4', array['Engancha un asa a cada lado de la polea, a la altura de los hombros.', 'Ponte en el centro de la máquina con los pies a la anchura de los hombros.', 'Agarra las asas en pronación y da un paso atrás para tensar los cables.', 'Inclínate un poco desde la cadera, con la espalda recta y el pecho alto.', 'Tira de las asas hacia abajo y cruzando el cuerpo, juntando las escápulas.']::text[]),
  ('7OeHptV', null, 'Dominadas supinas asistidas de pie', 'back', array['biceps', 'forearm']::text[], 'Máquina', 'Principiante', 'catalog/7OeHptV.mp4', array['Ajusta la máquina al nivel de asistencia que quieras.', 'Súbete a la plataforma y agarra las asas en pronación, algo más abierto que la anchura de los hombros.', 'Mantén el pecho alto y los hombros atrás, aprieta el core y flexiona un poco las rodillas.', 'Sube el cuerpo flexionando los codos y llevándolos hacia los costados.', 'Sigue tirando hasta pasar la barbilla por encima de la barra.']::text[]),
  ('mExgrF9', null, 'Dominadas en banco', 'back', array['biceps', 'forearm']::text[], 'Peso corporal', 'Intermedio', 'catalog/mExgrF9.mp4', array['Colócate debajo de una barra o una superficie horizontal resistente a la altura del pecho.', 'Agarra la barra o la superficie en pronación, algo más abierto que la anchura de los hombros.', 'Cuélgate con los brazos estirados del todo y el cuerpo recto.', 'Lleva el pecho hacia la barra o la superficie juntando las escápulas y flexionando los codos.', 'Sigue tirando hasta pasar la barbilla por encima de la barra o la superficie.']::text[]),
  ('JsOV1SU', null, 'Muscle up con lastre', 'back', array['biceps', 'triceps']::text[], 'Con lastre', 'Avanzado', 'catalog/JsOV1SU.mp4', array['Empieza colgado de la barra en pronación, con las manos algo más abiertas que los hombros.', 'Aprieta el core y sube el cuerpo hacia la barra, llevando el pecho por delante.', 'Al llegar arriba, cambia el agarre para que las palmas queden mirando hacia ti.', 'Sigue subiendo hasta que el pecho llegue a la barra y aguanta un momento.', 'Baja despacio a la posición inicial, controlando todo el movimiento.']::text[]),
  ('dmgMp3n', null, 'Remo inclinado con barra', 'back', array['biceps', 'forearm']::text[], 'Barra', 'Intermedio', 'catalog/dmgMp3n.mp4', array['Coloca un banco inclinado a 45 grados.', 'Túmbate boca abajo en el banco con el pecho contra la almohadilla y los pies apoyados en el suelo.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Mantén la espalda recta y el core apretado.', 'Tira de la barra hacia el pecho juntando las escápulas.']::text[]),
  ('kesXOpB', null, 'Remo declinado sentado en polea con agarre ancho', 'back', array['biceps', 'forearm']::text[], 'Polea', 'Principiante', 'catalog/kesXOpB.mp4', array['Siéntate en el banco declinado mirando a la polea, con los pies bien apoyados en los reposapiés.', 'Agarra el accesorio de la polea en pronación y con agarre ancho, palmas hacia abajo.', 'Échate un poco hacia atrás, con la espalda recta y el core apretado.', 'Tira del cable hacia la parte baja del pecho juntando las escápulas.', 'Aguanta un momento en la máxima contracción y suelta el cable despacio a la posición inicial.']::text[]),
  ('f4xtKBj', null, 'Dominadas asistidas de pie', 'back', array['biceps', 'forearm']::text[], 'Máquina', 'Principiante', 'catalog/f4xtKBj.mp4', array['Ajusta la máquina al peso y la altura que quieras.', 'Ponte de pie frente a la máquina con los pies a la anchura de los hombros.', 'Agarra las agarraderas en pronación, algo más abierto que la anchura de los hombros.', 'Aprieta dorsales y bíceps y sube hacia las asas.', 'Aguanta un momento arriba apretando la espalda.']::text[]),
  ('3xK09Sk', null, 'Remo en cuclillas con peso corporal', 'back', array['biceps']::text[], 'Peso corporal', 'Intermedio', 'catalog/3xK09Sk.mp4', array['Ponte de pie con los pies a la anchura de los hombros, agarrado a algo resistente o a unas cintas de suspensión con los brazos estirados.', 'Baja a la sentadilla con la espalda recta y las rodillas por detrás de las puntas.', 'Desde la sentadilla, tira del cuerpo hacia el punto de agarre juntando las escápulas.', 'Aguanta un momento arriba y baja el cuerpo despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('fXfqg1E', null, 'Dominada a una mano con lastre', 'back', array['biceps', 'forearm']::text[], 'Con lastre', 'Intermedio', 'catalog/fXfqg1E.mp4', array['Agarra la barra de dominadas en pronación, algo más abierto que la anchura de los hombros.', 'Cuélgate de la barra con el brazo estirado del todo y el cuerpo recto.', 'Aprieta el core y sube el cuerpo hacia la barra flexionando el codo y apretando la espalda.', 'Sigue tirando hasta pasar la barbilla por encima de la barra.', 'Baja el cuerpo a la posición inicial de forma controlada.']::text[]),
  ('wt6rwjk', null, 'Remo con mancuernas y rotación de muñeca', 'back', array['biceps', 'forearm']::text[], 'Mancuernas', 'Intermedio', 'catalog/wt6rwjk.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano en pronación.', 'Inclínate desde la cadera, con la espalda recta y las rodillas algo flexionadas.', 'Deja los brazos colgando, con las palmas hacia el cuerpo.', 'Aprieta el core y sube las mancuernas hacia el pecho, con los codos pegados al cuerpo.', 'Mientras subes las mancuernas, gira las palmas para que miren hacia fuera.']::text[]),
  ('veXwo0D', null, 'Remo sentado en el suelo con agarre ancho', 'back', array['biceps', 'forearm']::text[], 'Polea', 'Principiante', 'catalog/veXwo0D.mp4', array['Siéntate en el suelo con las piernas estiradas y la espalda recta.', 'Engancha un asa a la polea baja y colócate con la máquina detrás.', 'Agarra el asa en pronación y con agarre ancho, palmas hacia abajo.', 'Échate un poco atrás, con la espalda recta y el pecho alto.', 'Tira del asa hacia la cintura juntando las escápulas.']::text[]),
  ('7I6LNUG', null, 'Remo sentado en máquina', 'back', array['biceps', 'forearm']::text[], 'Máquina', 'Principiante', 'catalog/7I6LNUG.mp4', array['Ajusta la altura del asiento y los reposapiés a una posición cómoda.', 'Siéntate en la máquina con el pecho contra la almohadilla y los pies en los reposapiés.', 'Agarra las asas en pronación, a la anchura de los hombros.', 'Mantén la espalda recta y el core apretado.', 'Tira de las agarraderas hacia el cuerpo juntando las escápulas.']::text[]),
  ('v2DfH14', null, 'Remo a un brazo de pie con agarre cerrado', 'back', array['biceps', 'forearm']::text[], 'Peso corporal', 'Intermedio', 'catalog/v2DfH14.mp4', array['Ponte de pie con los pies a la anchura de los hombros, las rodillas algo flexionadas y una mancuerna en una mano con agarre neutro.', 'Inclínate hacia delante desde la cadera, con la espalda recta y el core apretado.', 'Sube la mancuerna hacia el pecho, con el codo pegado al cuerpo y juntando las escápulas.', 'Aguanta un momento arriba y baja la mancuerna despacio a la posición inicial.', 'Repite las repeticiones que quieras y cambia de lado.']::text[]),
  ('HMzLjXx', null, 'Dominadas con lastre', 'back', array['biceps', 'forearm']::text[], 'Con lastre', 'Intermedio', 'catalog/HMzLjXx.mp4', array['Agarra la barra de dominadas en pronación, algo más abierto que la anchura de los hombros.', 'Cuélgate de la barra con los brazos estirados del todo y el cuerpo recto.', 'Aprieta la espalda y sube el cuerpo hacia la barra, con los codos pegados al cuerpo.', 'Sigue tirando hasta pasar la barbilla por encima de la barra.', 'Aguanta un momento arriba y baja el cuerpo despacio a la posición inicial.']::text[]),
