  ('ZIViNh1', null, 'Remo a un brazo en banco inclinado con agarre invertido', 'back', array['biceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/ZIViNh1.mp4', array['Coloca un banco inclinado a 45 grados.', 'Deja una mancuerna en el suelo junto al banco.', 'Ponte de pie frente al banco con los pies a la anchura de los hombros.', 'Inclínate y apoya la rodilla y la mano izquierdas en el banco.', 'Coge la mancuerna con la mano derecha en pronación (palma hacia abajo).']::text[]),
  ('ZSJNetl', null, 'Remo alto de rodillas en polea', 'back', array['biceps']::text[], 'Polea', 'Principiante', 'catalog/ZSJNetl.mp4', array['Engancha una barra recta a la polea a la altura del pecho.', 'Ponte de rodillas frente a la polea y agarra la barra en pronación, con las manos a la anchura de los hombros.', 'Siéntate sobre los talones, con la espalda recta y el core apretado.', 'Tira de la barra hacia la parte alta del abdomen juntando las escápulas.', 'Aguanta un momento arriba y suelta la barra despacio a la posición inicial.']::text[]),
  ('aaXr7ld', null, 'Remo en T en máquina', 'back', array['biceps', 'forearm']::text[], 'Máquina', 'Principiante', 'catalog/aaXr7ld.mp4', array['Ajusta la altura del asiento y la plataforma para quedar bien alineado.', 'Siéntate en la máquina con el pecho contra la almohadilla y los pies apoyados en la plataforma.', 'Agarra las agarraderas en pronación, algo más abierto que la anchura de los hombros.', 'Mantén la espalda recta y aprieta el core.', 'Tira de las asas hacia el tronco juntando las escápulas.']::text[]),
  ('tig3PXb', null, 'Remo de pie con agarre cerrado', 'back', array['biceps', 'forearm']::text[], 'Peso corporal', 'Intermedio', 'catalog/tig3PXb.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las rodillas algo flexionadas.', 'Inclínate hacia delante, con la espalda recta y el core apretado.', 'Estira los brazos hacia delante, agarrando la barra o las asas con agarre cerrado.', 'Tira de la barra o las asas hacia el cuerpo juntando las escápulas.', 'Aguanta un momento arriba y vuelve despacio a la posición inicial.']::text[]),
  ('znLogoF', null, 'Pullover a press con barra', 'back', array['triceps']::text[], 'Barra', 'Intermedio', 'catalog/znLogoF.mp4', array['Túmbate en el banco con la cabeza en un extremo y los pies en el suelo.', 'Sujeta la barra en pronación (palmas hacia fuera) y estira los brazos encima del pecho.', 'Con los brazos estirados, baja la barra por detrás de la cabeza en arco hasta notar el estiramiento en los dorsales.', 'Aguanta un momento, invierte el movimiento y lleva la barra de vuelta encima del pecho.', 'Repite las repeticiones que quieras.']::text[]),
  ('9pQSkH8', null, 'Remo a dos brazos en banco inclinado con agarre invertido', 'back', array['biceps', 'forearm']::text[], 'Mancuernas', 'Intermedio', 'catalog/9pQSkH8.mp4', array['Coloca un banco inclinado a 45 grados.', 'Siéntate en el banco con el pecho contra el respaldo y los pies apoyados en el suelo.', 'Sujeta una mancuerna en cada mano en supinación.', 'Inclínate hacia delante y deja los brazos colgando, estirados del todo.', 'Sube las mancuernas hacia el pecho juntando las escápulas.']::text[]),
  ('yaMIo4D', null, 'Remo en banco inclinado con polea', 'back', array['biceps']::text[], 'Polea', 'Principiante', 'catalog/yaMIo4D.mp4', array['Coloca un banco inclinado a 45 grados y engancha un asa a la polea baja.', 'Siéntate en el banco mirando a la polea, con los pies apoyados y las rodillas algo flexionadas.', 'Agarra el asa en pronación y estira los brazos del todo por delante.', 'Inclínate desde la cadera con la espalda recta y el core apretado.', 'Tira del asa hacia el pecho llevando las escápulas atrás y flexionando los codos.']::text[]),
  ('xbkPfaw', null, 'Remo a un brazo de pie', 'back', array['biceps', 'forearm']::text[], 'Peso corporal', 'Intermedio', 'catalog/xbkPfaw.mp4', array['Ponte de pie con los pies a la anchura de los hombros, las rodillas algo flexionadas y una mancuerna en una mano.', 'Inclínate hacia delante desde la cadera, con la espalda recta y el core apretado.', 'Deja la mancuerna colgando por delante, con el brazo estirado del todo.', 'Sube la mancuerna hacia el pecho, con el codo pegado al cuerpo.', 'Junta las escápulas arriba del todo.']::text[]),
