  ('vptOQ4N', null, 'Flexiones profundas', 'chest', array['triceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/vptOQ4N.mp4', array['Empieza en plancha alta con las manos algo más abiertas que los hombros y el cuerpo en línea recta.', 'Baja el pecho hacia el suelo flexionando los codos, manteniéndolos pegados al cuerpo.', 'Empuja con las palmas para estirar los brazos y volver a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('7xI5MXA', null, 'Press de banca en polea', 'chest', array['triceps']::text[], 'Polea', 'Principiante', 'catalog/7xI5MXA.mp4', array['Ajusta la polea a la altura del pecho y engancha las asas.', 'Ponte de pie de espaldas a la máquina con los pies a la anchura de los hombros.', 'Agarra las asas en pronación y da un paso adelante para tensar los cables.', 'Planta bien los pies en el suelo y aprieta el core.', 'Flexiona los codos y lleva las manos a la altura de los hombros, con los codos a 90 grados.']::text[]),
  ('PAgTVaK', null, 'Fondos de pecho asistidos (de rodillas)', 'chest', array['triceps']::text[], 'Máquina', 'Principiante', 'catalog/PAgTVaK.mp4', array['Ajusta la máquina a la altura que quieras y apoya bien las rodillas en la almohadilla.', 'Agarra las asas con las palmas hacia abajo y los brazos estirados del todo.', 'Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.', 'Aguanta un momento y empuja para volver a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('A9qxk2F', null, 'Flexiones de arquero', 'chest', array['triceps']::text[], 'Peso corporal', 'Intermedio', 'catalog/A9qxk2F.mp4', array['Ponte en posición de flexión con las manos algo más abiertas que los hombros.', 'Estira un brazo hacia el lado, paralelo al suelo.', 'Baja el cuerpo flexionando los codos, con la espalda recta y el core apretado.', 'Empuja para volver a la posición inicial.', 'Repite con el otro lado, estirando el brazo contrario.']::text[]),
  ('PSlvNMs', null, 'Flexiones con caída y lastre', 'chest', array['triceps']::text[], 'Con lastre', 'Intermedio', 'catalog/PSlvNMs.mp4', array['Empieza en plancha alta con las manos algo más abiertas que los hombros y los pies juntos.', 'Baja el pecho hacia el suelo, con los codos pegados al cuerpo.', 'Con el pecho justo encima del suelo, empuja de forma explosiva despegando las manos.', 'Al empujar, lleva rápido las manos a los lados y algo hacia delante, dejando caer el cuerpo hacia el suelo.', 'Amortigua con las manos en la posición abierta y vuelve a bajar el pecho hacia el suelo.']::text[]),
  ('hl8DUh8', null, 'Press declinado con barra y agarre ancho', 'chest', array['triceps']::text[], 'Barra', 'Intermedio', 'catalog/hl8DUh8.mp4', array['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que la cadera.', 'Agarra la barra abierto, algo más ancho que la anchura de los hombros.', 'Baja la barra al pecho, con los codos abiertos.', 'Empuja la barra de vuelta a la posición inicial estirando los brazos del todo.', 'Repite las repeticiones que quieras.']::text[]),
  ('vi8EhoE', null, 'Pullover circular con mancuerna', 'chest', array['triceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/vi8EhoE.mp4', array['Túmbate en el banco con la cabeza en un extremo y los pies bien plantados en el suelo.', 'Sujeta una mancuerna con las dos manos y estira los brazos encima del pecho.', 'Con los brazos estirados, baja la mancuerna despacio por detrás de la cabeza en arco.', 'Aguanta un momento abajo y sube la mancuerna a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('0CXGHya', null, 'Cruces en polea', 'chest', array['triceps']::text[], 'Polea', 'Principiante', 'catalog/0CXGHya.mp4', array['Ajusta las poleas a la altura del pecho.', 'Ponte en el centro de la máquina con un pie por delante del otro.', 'Agarra las asas con las palmas hacia abajo y los brazos abiertos a los lados.', 'Da un paso adelante, con los brazos algo flexionados.', 'Con los codos algo flexionados, junta las manos delante del pecho.']::text[]),
  ('XgWyAiA', null, 'Fondos de pecho (en jaula de dominadas)', 'chest', array['triceps']::text[], 'Peso corporal', 'Intermedio', 'catalog/XgWyAiA.mp4', array['Ajusta las paralelas a una altura en la que las agarres cómodo.', 'Ponte entre las barras y apoya una mano en cada una, algo más abiertas que los hombros.', 'Sube de un impulso y estira los brazos, aguantando tu peso sobre las barras.', 'Flexiona las rodillas y cruza los tobillos por detrás.', 'Baja el cuerpo flexionando los codos, con el pecho alto y los hombros bajos.']::text[]),
