  ('GXoaSgn', null, 'Press de banca guillotina con barra', 'chest', array['triceps']::text[], 'Barra', 'Intermedio', 'catalog/GXoaSgn.mp4', array['Túmbate en el banco con los pies apoyados en el suelo y la espalda pegada al banco.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Baja la barra despacio hacia el cuello, con los codos abiertos.', 'Aguanta un momento con la barra justo encima del cuello.', 'Empuja la barra de vuelta a la posición inicial estirando los brazos del todo.']::text[]),
