  ('wDN97Ca', null, 'Press de pecho interior en máquina', 'chest', array['triceps']::text[], 'Máquina', 'Principiante', 'catalog/wDN97Ca.mp4', array['Ajusta la altura del asiento y colócate con la espalda bien pegada al respaldo.', 'Agarra las asas en pronación y coloca los codos a 90 grados.', 'Empuja las asas hacia delante hasta estirar los brazos del todo, soltando el aire.', 'Aguanta un momento al final y vuelve despacio a la posición inicial cogiendo aire.', 'Repite las repeticiones que quieras.']::text[]),
  ('7E06s6d', null, 'Flexiones con toque al pecho', 'chest', array['triceps']::text[], 'Peso corporal', 'Intermedio', 'catalog/7E06s6d.mp4', array['Empieza en plancha alta con las manos algo más abiertas que los hombros y el cuerpo en línea recta.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos pegados al cuerpo.', 'Al bajar, tócate el pecho con la mano derecha.', 'Empuja para volver a la posición inicial.', 'Repite el movimiento, esta vez tocándote el pecho con la mano izquierda.']::text[]),
  ('1qrWgZ2', null, 'Press martillo declinado con mancuernas', 'chest', array['triceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/1qrWgZ2.mp4', array['Túmbate en un banco declinado con los pies sujetos y la cabeza más baja que la cadera.', 'Sujeta una mancuerna en cada mano con las palmas enfrentadas y los brazos estirados encima del pecho.', 'Baja las mancuernas a los lados del pecho, con los codos algo flexionados.', 'Empuja las mancuernas de vuelta a la posición inicial, estirando los brazos del todo.', 'Repite las repeticiones que quieras.']::text[]),
  ('2Pya1cP', null, 'Press declinado en polea', 'chest', array['triceps']::text[], 'Polea', 'Principiante', 'catalog/2Pya1cP.mp4', array['Ajusta la polea en posición declinada.', 'Siéntate en el banco declinado mirando a la polea.', 'Agarra las asas en pronación y colócalas a la altura del pecho.', 'Mantén los pies apoyados en el suelo y la espalda bien pegada al banco.', 'Suelta el aire y empuja las asas hacia fuera, estirando los brazos del todo.']::text[]),
  ('trqKQv2', null, 'Press de banca en multipower', 'chest', array['triceps']::text[], 'Máquina', 'Principiante', 'catalog/trqKQv2.mp4', array['Ajusta la barra del multipower a la altura del pecho.', 'Túmbate en el banco con los pies bien plantados en el suelo.', 'Agarra la barra en pronación algo más abierto que la anchura de los hombros.', 'Saca la barra del soporte y bájala hacia el pecho, con los codos recogidos.', 'Aguanta un momento cuando la barra toque el pecho.']::text[]),
  ('wigSg76', null, 'Flexiones con palmada', 'chest', array['triceps']::text[], 'Peso corporal', 'Intermedio', 'catalog/wigSg76.mp4', array['Empieza en plancha alta con las manos algo más abiertas que los hombros.', 'Baja el cuerpo hacia el suelo flexionando los codos, con el core apretado.', 'Empuja con las palmas de forma explosiva para despegar el cuerpo del suelo.', 'En el aire, da una palmada antes de caer en la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('Vh0GsK4', null, 'Press inclinado en polea', 'chest', array['triceps']::text[], 'Polea', 'Principiante', 'catalog/Vh0GsK4.mp4', array['Pon el banco a 45 grados de inclinación.', 'Engancha las asas a las poleas altas.', 'Siéntate en el banco mirando a la polea, con los pies apoyados en el suelo.', 'Agarra las asas en pronación y llévalas a la altura de los hombros.', 'Empuja las asas hacia delante y arriba hasta estirar los brazos del todo.']::text[]),
  ('ETZfAbZ', null, 'Press declinado en multipower', 'chest', array['triceps']::text[], 'Máquina', 'Principiante', 'catalog/ETZfAbZ.mp4', array['Ajusta el banco declinado al ángulo que quieras.', 'Túmbate en el banco con los pies sujetos bajo las almohadillas.', 'Agarra la barra en pronación algo más abierto que la anchura de los hombros.', 'Saca la barra del soporte y bájala despacio hacia el pecho, con los codos recogidos.', 'Aguanta un momento abajo y empuja la barra de vuelta a la posición inicial.']::text[]),
  ('CMAxnsG', null, 'Flexiones del reloj', 'chest', array['triceps']::text[], 'Peso corporal', 'Intermedio', 'catalog/CMAxnsG.mp4', array['Empieza en plancha alta con las manos justo debajo de los hombros y el cuerpo en línea recta.', 'Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos pegados al cuerpo.', 'Al bajar, gira el cuerpo a la izquierda estirando el brazo izquierdo hacia el lado.', 'Empuja para volver a la posición inicial girando el cuerpo al centro.', 'Repite la flexión, esta vez girando a la derecha y estirando el brazo derecho hacia el lado.']::text[]),
  ('JsKq9so', null, 'Press de banca con barra y agarre ancho', 'chest', array['triceps']::text[], 'Barra', 'Intermedio', 'catalog/JsKq9so.mp4', array['Túmbate en el banco con los pies apoyados en el suelo y la espalda pegada al banco.', 'Agarra la barra abierto, algo más ancho que la anchura de los hombros.', 'Saca la barra del soporte y sujétala justo encima del pecho con los brazos estirados del todo.', 'Baja la barra despacio hacia el pecho, con los codos algo abiertos.', 'Aguanta un momento cuando la barra toque el pecho y empújala de vuelta a la posición inicial.']::text[]),
  ('reFHapa', null, 'Aperturas declinadas con giro', 'chest', array['triceps']::text[], 'Mancuernas', 'Principiante', 'catalog/reFHapa.mp4', array['Túmbate en un banco declinado con la cabeza más baja que la cadera.', 'Sujeta una mancuerna en cada mano con las palmas enfrentadas y los brazos estirados encima del pecho.', 'Baja las mancuernas a los lados en un arco amplio hasta notar el estiramiento en el pecho.', 'Al bajar las mancuernas, gira las muñecas para que abajo las palmas miren hacia delante.', 'Invierte el movimiento y sube las mancuernas a la posición inicial, apretando el pecho arriba.']::text[]),
  ('tBWXbIT', null, 'Aperturas inclinadas en polea', 'chest', array['triceps']::text[], 'Polea', 'Principiante', 'catalog/tBWXbIT.mp4', array['Pon la polea en posición baja y engancha las asas.', 'Siéntate en un banco inclinado con la espalda contra el respaldo y los pies apoyados en el suelo.', 'Agarra las asas en pronación y estira los brazos por delante.', 'Con los codos algo flexionados, abre los brazos a los lados de forma controlada.', 'Aguanta un momento con todo estirado y vuelve despacio a la posición inicial.']::text[]),
  ('MY9P1WA', null, 'Press declinado en multipower con agarre invertido', 'chest', array['triceps']::text[], 'Máquina', 'Principiante', 'catalog/MY9P1WA.mp4', array['Ajusta el multipower en posición declinada.', 'Túmbate en el banco con los pies sujetos bajo las almohadillas.', 'Agarra la barra en supinación, con las manos algo más abiertas que los hombros.', 'Saca la barra del soporte y bájala hacia el pecho, con los codos recogidos.', 'Aguanta un momento abajo y empuja la barra de vuelta a la posición inicial.']::text[]),
  ('b2Uoz54', null, 'Elevaciones frontales con barra', 'shoulders', array['biceps', 'triceps']::text[], 'Barra', 'Principiante', 'catalog/b2Uoz54.mp4', array['Ponte de pie con los pies a la anchura de los hombros y sujeta la barra delante de los muslos en pronación.', 'Con los brazos estirados, sube la barra hacia delante y arriba hasta la altura de los hombros.', 'Aguanta un momento arriba y baja la barra despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('izMnLqz', null, 'Press lateral alterno con mancuernas', 'shoulders', array['triceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/izMnLqz.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano a la altura de los hombros.', 'Empuja una mancuerna por encima de la cabeza y deja la otra a la altura del hombro.', 'Baja esa mancuerna al hombro mientras subes la otra por encima de la cabeza.', 'Sigue alternando lados durante las repeticiones que quieras.']::text[]),
  ('KHPZL0b', null, 'Press de hombro alterno en polea', 'shoulders', array['triceps', 'back']::text[], 'Polea', 'Principiante', 'catalog/KHPZL0b.mp4', array['Ponte de pie con los pies a la anchura de los hombros y agarra las asas de la polea en pronación.', 'Coloca las manos a la altura de los hombros, con las palmas hacia delante.', 'Mantén el core apretado y la espalda recta.', 'Empuja un asa hacia arriba y adelante hasta estirar el brazo del todo.', 'Aguanta un momento arriba y baja el asa despacio a la posición inicial.']::text[]),
  ('myfUsKf', null, 'Pájaros sentado en máquina', 'shoulders', '{}', 'Máquina', 'Principiante', 'catalog/myfUsKf.mp4', array['Ajusta la altura del asiento y colócate con el pecho contra la almohadilla y los pies apoyados en el suelo.', 'Agarra las asas en pronación y mantén los brazos algo flexionados.', 'Suelta el aire y junta las escápulas mientras llevas las asas atrás y hacia fuera.', 'Aguanta un momento en la máxima contracción, coge aire y vuelve despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('e4aFmFY', null, 'Elevaciones frontales con lastre', 'shoulders', array['biceps', 'forearm']::text[], 'Con lastre', 'Principiante', 'catalog/e4aFmFY.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano, con las palmas mirando a los muslos.', 'Con los brazos estirados, suelta el aire y sube las mancuernas por delante hasta la altura de los hombros.', 'Aguanta un momento arriba, coge aire y baja las mancuernas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('xHKN2s8', null, 'Arrancada a un brazo con barra', 'shoulders', array['trapezius', 'forearm']::text[], 'Barra', 'Avanzado', 'catalog/xHKN2s8.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Sujeta la barra en pronación, con las manos algo más abiertas que los hombros.', 'Flexiona las rodillas y baja la cadera a la sentadilla, con la espalda recta y el pecho alto.', 'Estira cadera, rodillas y tobillos de forma explosiva, impulsando la barra hacia arriba.', 'Cuando la barra llegue a la altura del pecho, tira de ella con el brazo manteniéndola pegada al cuerpo.']::text[]),
  ('eOrFCnx', null, 'Press Arnold con mancuernas (variante)', 'shoulders', array['triceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/eOrFCnx.mp4', array['Siéntate en un banco con respaldo y sujeta una mancuerna en cada mano a la altura de los hombros, con las palmas hacia ti y los codos flexionados.', 'Empuja las mancuernas hacia arriba hasta estirar los brazos del todo, con las palmas hacia delante.', 'Gira las muñecas mientras subes, de modo que arriba las palmas queden mirando hacia delante.', 'Aguanta un momento arriba y baja las mancuernas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('aqvSOQE', null, 'Pájaros cruzados en polea', 'shoulders', '{}', 'Polea', 'Principiante', 'catalog/aqvSOQE.mp4', array['Engancha un asa a cada polea baja y ponte en el centro de la máquina de cruces.', 'Agarra las asas en pronación (palmas hacia abajo) y da un paso adelante, con los pies a la anchura de los hombros.', 'Flexiona un poco las rodillas e inclínate hacia delante, con la espalda recta y el abdomen apretado.', 'Con los brazos abiertos a los lados y los codos algo flexionados, suelta el aire y junta las escápulas mientras llevas los cables atrás y arriba, como en unos pájaros.', 'Aguanta un momento en la máxima contracción, coge aire y vuelve despacio a la posición inicial.']::text[]),
  ('67n3r98', null, 'Press de hombro en máquina', 'shoulders', array['triceps']::text[], 'Máquina', 'Principiante', 'catalog/67n3r98.mp4', array['Ajusta la altura del asiento y colócate con la espalda contra el respaldo.', 'Agarra las asas en pronación y colócalas a la altura de los hombros.', 'Empuja las asas hacia arriba hasta estirar los brazos, sin bloquear los codos.', 'Aguanta un momento arriba y baja las asas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('7uFJuXp', null, 'Zancada de rodillas con balanceo y lastre', 'shoulders', array['triceps']::text[], 'Con lastre', 'Intermedio', 'catalog/7uFJuXp.mp4', array['Empieza de rodillas, con las rodillas a la anchura de la cadera y la espalda recta.', 'Sujeta un peso en cada mano, con los brazos estirados hacia abajo por delante.', 'Aprieta el core y lleva los pesos arriba en un balanceo, con los brazos estirados.', 'Baja los pesos a la posición inicial y repite las repeticiones que quieras.']::text[]),
  ('Ln9iTbU', null, 'Elevaciones posteriores con barra', 'shoulders', array['trapezius']::text[], 'Barra', 'Principiante', 'catalog/Ln9iTbU.mp4', array['Ponte de pie con los pies a la anchura de los hombros y sujeta la barra en pronación, con las palmas hacia abajo.', 'Flexiona un poco las rodillas e inclínate hacia delante desde la cadera, con la espalda recta.', 'Sube la barra a los lados, con los brazos estirados, hasta dejarlos paralelos al suelo.', 'Aguanta un momento arriba y baja la barra despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('3d7wHyd', null, 'Press sentado en banco con mancuernas', 'shoulders', array['triceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/3d7wHyd.mp4', array['Siéntate en un banco con una mancuerna en cada mano, apoyadas en los muslos.', 'Échate atrás y coloca las mancuernas a los lados del pecho, con las palmas hacia delante.', 'Empuja las mancuernas hacia arriba hasta estirar los brazos del todo.', 'Aguanta un momento arriba y baja las mancuernas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('hvHhCv8', null, 'Elevaciones frontales en polea', 'shoulders', array['triceps', 'forearm']::text[], 'Polea', 'Principiante', 'catalog/hvHhCv8.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las rodillas algo flexionadas.', 'Sujeta el asa en pronación, palmas hacia abajo, con los brazos estirados por delante.', 'Con los brazos estirados, sube el asa hasta la altura de los hombros.', 'Aguanta un momento arriba y baja el asa despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
