  ('G61cXLk', null, 'Remo posterior de rodillas en polea con cuerda', 'shoulders', array['biceps']::text[], 'Polea', 'Principiante', 'catalog/G61cXLk.mp4', array['Engancha una cuerda a la polea baja y ponte de rodillas frente a la máquina.', 'Agarra la cuerda con agarre neutro (palmas enfrentadas) y estira los brazos del todo por delante.', 'Con la espalda recta y el core apretado, tira de la cuerda hacia el cuerpo llevando las escápulas atrás.', 'Junta las escápulas al final del movimiento y aguanta un instante.', 'Suelta la tensión despacio y vuelve a la posición inicial.']::text[]),
  ('903mzG8', null, 'Press de hombro en multipower', 'shoulders', array['triceps', 'back']::text[], 'Máquina', 'Principiante', 'catalog/903mzG8.mp4', array['Ajusta la altura del asiento y colócate en el multipower con los pies a la anchura de los hombros.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Saca la barra del soporte y colócala a la altura de los hombros, con los codos flexionados y las palmas hacia delante.', 'Empuja la barra hacia arriba hasta estirar los brazos del todo sobre la cabeza.', 'Aguanta un momento arriba y baja la barra despacio a la altura de los hombros.']::text[]),
  ('kTbSH9h', null, 'Press militar sentado con barra', 'shoulders', array['triceps', 'back']::text[], 'Barra', 'Intermedio', 'catalog/kTbSH9h.mp4', array['Siéntate en un banco con la espalda recta y los pies apoyados en el suelo.', 'Sujeta la barra en pronación, algo más abierto que la anchura de los hombros.', 'Saca la barra del soporte y llévala a la altura de los hombros, con los codos flexionados y las palmas hacia delante.', 'Empuja la barra por encima de la cabeza estirando los brazos del todo.', 'Aguanta un momento arriba y baja la barra despacio a la altura de los hombros.']::text[]),
  ('aTNKZiC', null, 'Elevación lateral inclinada a un brazo', 'shoulders', array['triceps']::text[], 'Mancuernas', 'Principiante', 'catalog/aTNKZiC.mp4', array['Siéntate en un banco inclinado con una mancuerna en una mano, apoyada en el muslo.', 'Inclínate hacia delante y apoya el brazo contra la cara interna del muslo.', 'Sube la mancuerna hacia el lado, con el brazo algo flexionado y la palma hacia abajo.', 'Sigue subiendo hasta que el brazo quede paralelo al suelo.', 'Aguanta un momento arriba y baja la mancuerna despacio a la posición inicial.']::text[]),
  ('ht8xDrP', null, 'Press militar de pie tras nuca en multipower', 'shoulders', array['triceps', 'back']::text[], 'Máquina', 'Principiante', 'catalog/ht8xDrP.mp4', array['Ajusta la altura del asiento del multipower para que la barra quede a la altura de los hombros.', 'Ponte de pie con los pies a la anchura de los hombros y las rodillas algo flexionadas.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Saca la barra del soporte y da un paso atrás, con los pies bien plantados.', 'Coloca la barra por detrás de la cabeza, apoyada en la parte alta del trapecio.']::text[]),
