  ('yUdIGNs', null, 'Remo posterior en polea con estribos', 'shoulders', array['biceps']::text[], 'Polea', 'Principiante', 'catalog/yUdIGNs.mp4', array['Engancha un estribo a la polea baja y ponte de pie frente a la máquina.', 'Agarra el asa con la mano izquierda y da un paso atrás con el pie derecho, quedando algo en diagonal.', 'Flexiona un poco las rodillas e inclínate desde la cadera, con la espalda recta y el core apretado.', 'Con el brazo izquierdo estirado y la palma hacia abajo, tira del asa hacia el pecho llevando la escápula atrás.', 'Aguanta un momento arriba apretando la escápula.']::text[]),
  ('xi0yckC', null, 'Elevación de hombro inclinada con barra', 'abdomen', '{}', 'Barra', 'Principiante', 'catalog/xi0yckC.mp4', array['Coloca un banco inclinado a 45 grados.', 'Siéntate en el banco con la espalda contra el respaldo y los pies apoyados en el suelo.', 'Sujeta la barra en pronación, algo más abierto que la anchura de los hombros.', 'Sube la barra a la altura de los hombros, con los codos algo flexionados.', 'Sube la barra despacio por encima de la cabeza, estirando los brazos del todo.']::text[]),
  ('6e2DcYX', null, 'Elevación de hombro inclinada con mancuernas', 'abdomen', '{}', 'Mancuernas', 'Principiante', 'catalog/6e2DcYX.mp4', array['Pon un banco inclinado a 45 grados y siéntate con una mancuerna en cada mano, palmas hacia abajo.', 'Apoya las mancuernas en los muslos y échate atrás en el banco.', 'Ayúdate de los muslos para subir las mancuernas a la altura de los hombros y gira las muñecas hasta que las palmas miren hacia delante.', 'Suelta el aire y sube las mancuernas despacio por encima de la cabeza, con los codos algo flexionados.', 'Aguanta un momento arriba, coge aire y baja las mancuernas despacio a la altura de los hombros.']::text[]),
  ('MvQPqVW', null, 'Lanzamiento de judo en polea', 'abdomen', array['obliques']::text[], 'Polea', 'Principiante', 'catalog/MvQPqVW.mp4', array['Ponte de pie frente a la polea con los pies a la anchura de los hombros.', 'Sujeta el asa con las dos manos a la altura del pecho, palmas hacia abajo.', 'Aprieta el core y gira el tronco a la derecha, tirando del cable cruzando el cuerpo.', 'Al girar, pivota sobre el pie de atrás y deja que la cadera acompañe.', 'Estira los brazos del todo y termina el movimiento pasando el asa por encima del hombro.']::text[]),
  ('CqhoytW', null, 'Elevación de cadera en multipower', 'abdomen', array['glutes', 'hamstrings']::text[], 'Máquina', 'Principiante', 'catalog/CqhoytW.mp4', array['Colócate en el multipower con la espalda apoyada y los pies a la anchura de los hombros.', 'Pon las manos en la barra, algo más abiertas que los hombros.', 'Aprieta core y glúteos y empuja con los talones para despegar la cadera del suelo.', 'Sigue subiendo hasta que el cuerpo quede en línea recta de las rodillas a los hombros.', 'Aguanta un momento arriba y baja la cadera despacio a la posición inicial.']::text[]),
  ('2gPfomN', null, 'Abdominal 3/4', 'abdomen', '{}', 'Peso corporal', 'Intermedio', 'catalog/2gPfomN.mp4', array['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Pon las manos detrás de la cabeza con los codos abiertos.', 'Aprieta el abdomen y despega el tronco del suelo despacio, enrollándote hacia delante hasta unos 45 grados.', 'Aguanta un momento arriba y baja el tronco despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('wnEscH8', null, 'Abdominal con press de barra', 'abdomen', '{}', 'Barra', 'Intermedio', 'catalog/wnEscH8.mp4', array['Túmbate boca arriba en una esterilla con las rodillas flexionadas y los pies apoyados.', 'Sujeta la barra en pronación, apoyada en el pecho.', 'Aprieta el abdomen y despega el tronco del suelo despacio, enrollándote hacia delante hasta unos 45 grados.', 'Aguanta un momento arriba y baja el tronco despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('IpONWYv', null, 'Flexión lateral con mancuerna', 'abdomen', array['obliques']::text[], 'Mancuernas', 'Intermedio', 'catalog/IpONWYv.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en una mano, colgando al costado.', 'Con la espalda recta y el core apretado, inclínate despacio hacia el lado contrario a la mancuerna, bajando el peso hasta donde llegues cómodo.', 'Aguanta un momento y vuelve despacio a la posición inicial.', 'Repite las repeticiones que quieras y cambia de lado.']::text[]),
  ('WW95auq', null, 'Crunch de rodillas en polea', 'abdomen', array['obliques']::text[], 'Polea', 'Principiante', 'catalog/WW95auq.mp4', array['Engancha una cuerda a la polea alta y ponte de rodillas de espaldas a la máquina.', 'Sujeta la cuerda con las dos manos y colócala detrás de la cabeza, con los codos abiertos.', 'Con la cadera quieta, flexiona el tronco llevándolo hacia los muslos.', 'Aguanta un momento abajo y vuelve despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('ayAHcEm', null, 'Elevaciones de hombro inclinadas en multipower', 'abdomen', '{}', 'Máquina', 'Principiante', 'catalog/ayAHcEm.mp4', array['Ajusta el multipower en posición inclinada.', 'Ponte de pie frente a la máquina con los pies a la anchura de los hombros.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Mantén la espalda recta y el core apretado.', 'Sube la barra hacia el techo llevando los codos por delante.']::text[]),
  ('Hy9D21L', null, 'Flexión lateral a 45°', 'abdomen', array['obliques']::text[], 'Peso corporal', 'Intermedio', 'catalog/Hy9D21L.mp4', array['Ponte de pie con los pies a la anchura de los hombros y los brazos estirados a los costados.', 'Con la espalda recta y el core apretado, inclina el tronco despacio hacia un lado, bajando la mano hacia la rodilla.', 'Aguanta un momento abajo y vuelve despacio a la posición inicial.', 'Repite con el otro lado.', 'Sigue alternando lados durante las repeticiones que quieras.']::text[]),
  ('s8nrDXF', null, 'Crunch con lastre', 'abdomen', array['obliques']::text[], 'Con lastre', 'Principiante', 'catalog/s8nrDXF.mp4', array['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Sujeta un disco o una mancuerna sobre el pecho.', 'Aprieta el abdomen y despega el tronco del suelo, enrollándote hasta levantar las escápulas.', 'Aguanta un momento arriba y baja el tronco despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('7M66AVi', null, 'Rueda abdominal con barra', 'abdomen', '{}', 'Barra', 'Intermedio', 'catalog/7M66AVi.mp4', array['Ponte de rodillas en el suelo y sujeta la barra con las dos manos, a la anchura de los hombros.', 'Rueda la barra hacia delante estirando los brazos, con el core apretado.', 'Sigue rodando hasta quedar estirado del todo, con los brazos por encima de la cabeza.', 'Aguanta un momento y rueda la barra de vuelta hacia las rodillas, controlando.', 'Repite las repeticiones que quieras.']::text[]),
  ('RqOtqD7', null, 'Crunch inverso en polea', 'abdomen', '{}', 'Polea', 'Principiante', 'catalog/RqOtqD7.mp4', array['Engancha un cable a la polea baja y túmbate boca arriba en una esterilla.', 'Sujeta el cable con las dos manos y estira los brazos hacia el techo.', 'Flexiona las rodillas y sube las piernas, llevando los muslos hacia el pecho.', 'Con el tronco estable, lleva la pelvis hacia el pecho despegando la cadera de la esterilla.', 'Aguanta un momento arriba y baja la cadera despacio a la posición inicial.']::text[]),
  ('qaZVsGk', null, 'Toque de talones alterno', 'abdomen', array['obliques']::text[], 'Peso corporal', 'Intermedio', 'catalog/qaZVsGk.mp4', array['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Estira los brazos a los lados, paralelos al suelo.', 'Aprieta el abdomen, despega los hombros del suelo y lleva la mano derecha hacia el talón derecho.', 'Vuelve a la posición inicial y repite hacia la izquierda, llevando la mano izquierda al talón izquierdo.', 'Sigue alternando lados durante las repeticiones que quieras.']::text[]),
  ('EZeDVzO', null, 'Abdominal declinado con lastre', 'abdomen', '{}', 'Con lastre', 'Intermedio', 'catalog/EZeDVzO.mp4', array['Túmbate en un banco declinado con los pies sujetos bajo las almohadillas.', 'Pon las manos detrás de la cabeza o cruzadas sobre el pecho.', 'Aprieta el abdomen y despega el tronco del banco despacio, enrollándote hasta quedar perpendicular al suelo.', 'Aguanta un momento arriba y baja el tronco despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('Gxg9lDc', null, 'Rueda abdominal con barra desde banco', 'abdomen', array['triceps']::text[], 'Barra', 'Intermedio', 'catalog/Gxg9lDc.mp4', array['Empieza de rodillas en el suelo, con una barra apoyada en un banco delante de ti.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Con el core apretado y la espalda recta, rueda la barra despacio hacia delante estirando los brazos.', 'Sigue rodando la barra hasta quedar estirado del todo, con los brazos por encima de la cabeza.', 'Aguanta un momento estirado del todo y rueda la barra de vuelta hacia el cuerpo, a la posición inicial.']::text[]),
  ('d9Xaxq6', null, 'Giros rusos en polea sobre fitball', 'abdomen', array['obliques']::text[], 'Polea', 'Principiante', 'catalog/d9Xaxq6.mp4', array['Siéntate en un fitball con los pies apoyados en el suelo y las rodillas a 90 grados.', 'Sujeta el asa con las dos manos y estira los brazos por delante.', 'Échate un poco hacia atrás manteniendo la espalda recta y el core apretado.', 'Gira el tronco a la derecha, llevando el asa hacia la cadera derecha.', 'Aguanta un momento y gira el tronco a la izquierda, llevando el asa hacia la cadera izquierda.']::text[]),
  ('uWpxD4v', null, 'Balanceo colgado con rodillas flexionadas', 'abdomen', '{}', 'Peso corporal', 'Intermedio', 'catalog/uWpxD4v.mp4', array['Cuélgate de la barra con los brazos estirados del todo y las rodillas a 90 grados.', 'Aprieta el core y sube las rodillas hacia el pecho, acercándolas todo lo posible a los codos.', 'Baja las piernas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
