  ('dFSNDOA', null, 'Giro sentado con barra', 'abdomen', array['obliques']::text[], 'Barra', 'Intermedio', 'catalog/dFSNDOA.mp4', array['Siéntate en un banco plano con los pies apoyados en el suelo y las rodillas flexionadas.', 'Sujeta la barra con las dos manos delante del pecho, con los codos algo flexionados.', 'Aprieta el core y gira el tronco despacio hacia un lado, con la espalda recta.', 'Aguanta un momento al final del giro y vuelve despacio a la posición inicial.', 'Repite el giro hacia el otro lado.']::text[]),
  ('8xUv4J7', null, 'Crunch sentado en polea', 'abdomen', array['obliques']::text[], 'Polea', 'Principiante', 'catalog/8xUv4J7.mp4', array['Siéntate en la máquina de polea con los pies apoyados en el suelo y las rodillas flexionadas.', 'Sujeta el asa con las dos manos y colócala detrás de la cabeza.', 'Aprieta el abdomen y enrolla el tronco despacio hacia delante, llevando el pecho a las rodillas.', 'Aguanta un momento arriba y vuelve despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('PXTIwgu', null, 'Balanceo colgado con piernas rectas', 'abdomen', '{}', 'Peso corporal', 'Intermedio', 'catalog/PXTIwgu.mp4', array['Cuélgate de la barra con los brazos estirados del todo y las piernas rectas.', 'Aprieta el core y sube las piernas por delante hasta dejarlas paralelas al suelo.', 'Aguanta un momento arriba y baja las piernas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('fZFZ704', null, 'Giro ruso con lastre', 'abdomen', array['obliques']::text[], 'Con lastre', 'Intermedio', 'catalog/fZFZ704.mp4', array['Siéntate en el suelo con las rodillas flexionadas y los pies apoyados.', 'Sujeta un peso o un balón medicinal con las dos manos delante del pecho.', 'Échate un poco hacia atrás, con la espalda recta y el core apretado.', 'Gira el tronco despacio a la derecha, llevando el peso hacia el suelo por ese lado.', 'Aguanta un momento y gira el tronco a la izquierda, llevando el peso hacia el suelo por ese lado.']::text[]),
  ('i4JkUaL', null, 'Flexión lateral con barra (variante)', 'abdomen', array['obliques']::text[], 'Barra', 'Intermedio', 'catalog/i4JkUaL.mp4', array['Ponte de pie con los pies a la anchura de los hombros y sujeta la barra con las dos manos, palmas hacia abajo.', 'Mantén la espalda recta y el core apretado durante todo el ejercicio.', 'Inclina el tronco despacio a la derecha, bajando la barra hacia la rodilla derecha.', 'Aguanta un momento y vuelve a la posición inicial.', 'Repite el movimiento hacia la izquierda.']::text[]),
  ('UEjSrKI', null, 'Giro sentado en polea', 'abdomen', array['obliques']::text[], 'Polea', 'Principiante', 'catalog/UEjSrKI.mp4', array['Siéntate en la máquina de polea con los pies apoyados en el suelo y las rodillas algo flexionadas.', 'Sujeta el asa con las dos manos y estira los brazos por delante.', 'Con el core apretado, gira el tronco despacio hacia un lado, tirando del cable cruzando el cuerpo.', 'Aguanta un momento al final del recorrido y vuelve despacio a la posición inicial.', 'Repite con el otro lado.']::text[]),
  ('NAkmgdx', null, 'Abdominal completo con brazos sobre la cabeza', 'abdomen', '{}', 'Peso corporal', 'Intermedio', 'catalog/NAkmgdx.mp4', array['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Estira los brazos por encima de la cabeza.', 'Aprieta el abdomen y despega el tronco del suelo despacio, enrollándote hasta quedar sentado.', 'Aguanta un momento arriba y baja el tronco despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('s34Y4LR', null, 'Giro sentado con lastre en fitball', 'abdomen', array['obliques']::text[], 'Con lastre', 'Intermedio', 'catalog/s34Y4LR.mp4', array['Siéntate en un fitball con los pies apoyados en el suelo y las rodillas a 90 grados.', 'Sujeta un disco o una mancuerna con las dos manos pegado al pecho.', 'Aprieta el core y gira el tronco despacio hacia un lado, con la cadera quieta.', 'Aguanta un momento al final del giro y vuelve despacio a la posición inicial.', 'Repite el giro hacia el otro lado.']::text[]),
  ('G7xoEzr', null, 'Elevación de piernas alterna sentado con barra', 'abdomen', '{}', 'Barra', 'Principiante', 'catalog/G7xoEzr.mp4', array['Siéntate en un banco con la espalda recta y la barra apoyada sobre los muslos.', 'Con las piernas estiradas, sube una todo lo que puedas manteniendo la otra en el suelo.', 'Baja esa pierna y repite con la otra.', 'Sigue alternando piernas durante las repeticiones que quieras.']::text[]),
  ('wPypxFY', null, 'Flexión lateral en polea', 'abdomen', array['obliques']::text[], 'Polea', 'Principiante', 'catalog/wPypxFY.mp4', array['Ponte de pie con los pies a la anchura de los hombros y agarra el asa con una mano.', 'Mantén la espalda recta y el core apretado.', 'Inclínate despacio hacia el lado, bajando el asa hacia la rodilla.', 'Aguanta un momento y vuelve a la posición inicial.', 'Repite con el otro lado.']::text[]),
  ('5VXmnV5', null, 'Plancha lateral inclinada sin peso', 'abdomen', array['obliques']::text[], 'Peso corporal', 'Intermedio', 'catalog/5VXmnV5.mp4', array['Empieza tumbado de lado con las piernas estiradas y una encima de la otra.', 'Apoya el antebrazo en el suelo justo debajo del hombro, con el codo a 90 grados.', 'Aprieta el core y despega la cadera del suelo, dejando el cuerpo en línea recta de la cabeza a los pies.', 'Aguanta esa posición el tiempo que quieras.', 'Baja la cadera al suelo y repite con el otro lado.']::text[]),
  ('6bOA1Oi', null, 'Flexión lateral con lastre en fitball', 'abdomen', array['obliques']::text[], 'Con lastre', 'Intermedio', 'catalog/6bOA1Oi.mp4', array['Siéntate en un fitball con los pies a la anchura de los hombros y apoyados en el suelo.', 'Sujeta un peso en una mano y pon la otra en la cadera.', 'Aprieta el core e inclínate despacio hacia el lado del peso, con la espalda recta.', 'Aguanta un momento abajo y vuelve despacio a la posición inicial.', 'Repite las repeticiones que quieras y cambia de lado.']::text[]),
  ('xnInPfE', null, 'Rueda abdominal de pie con barra', 'abdomen', '{}', 'Barra', 'Intermedio', 'catalog/xnInPfE.mp4', array['Ponte de pie con los pies a la anchura de los hombros y la barra sujeta con las dos manos delante de los muslos.', 'Aprieta el core y rueda la barra despacio hacia el suelo, con la espalda recta y los brazos estirados.', 'Sigue rodando la barra hasta quedar estirado del todo, con las manos justo encima de la cabeza.', 'Aguanta un momento y rueda la barra de vuelta hacia los muslos, controlando y con el core apretado.', 'Repite las repeticiones que quieras.']::text[]),
  ('Y7YcmIJ', null, 'Sentadilla frontal en banco con barra', 'quads', array['hamstrings', 'glutes', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/Y7YcmIJ.mp4', array['Empieza de pie con los pies a la anchura de los hombros y la barra apoyada en la parte alta del pecho, justo bajo la clavícula.', 'Sujeta la barra en pronación, con los codos altos y los brazos paralelos al suelo.', 'Baja a la sentadilla flexionando rodillas y cadera, con la espalda recta y el pecho alto.', 'Aguanta un momento abajo y empuja con los talones para volver a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('gFyFj9z', null, 'Zancada con subida al step y mancuernas', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Mancuernas', 'Intermedio', 'catalog/gFyFj9z.mp4', array['Ponte delante de un step o plataforma con una mancuerna en cada mano, palmas hacia el cuerpo.', 'Apoya el pie derecho en el step, con toda la planta sobre la superficie.', 'Empuja con el talón derecho y sube al step, llevando también el pie izquierdo.', 'Con los dos pies arriba, baja el izquierdo a la posición inicial manteniendo el derecho en el step.', 'Repite el movimiento alternando el pie con el que subes.']::text[]),
  ('hBGWILP', null, 'Aducción de cadera en polea', 'quads', array['glutes']::text[], 'Polea', 'Principiante', 'catalog/hBGWILP.mp4', array['Ponte la tobillera y colócate de pie frente a la polea.', 'Sepárate lo suficiente de la máquina para que el cable quede tenso.', 'Apoya las manos en la máquina para sujetarte.', 'Con la pierna estirada, llévala despacio cruzando el cuerpo hacia el centro.', 'Aguanta un momento al final y vuelve despacio a la posición inicial.']::text[]),
  ('Gu2rNJd', null, 'Sentadilla a la silla en multipower', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Máquina', 'Principiante', 'catalog/Gu2rNJd.mp4', array['Ajusta la barra del multipower a una altura cómoda.', 'Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Apoya la barra en la parte alta de la espalda, sobre el trapecio.', 'Aprieta el core y mantén el pecho alto mientras bajas despacio flexionando rodillas y cadera.', 'Sigue bajando hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.']::text[]),
  ('SaDOwk7', null, 'Salto hacia atrás', 'quads', array['hamstrings', 'glutes', 'calves']::text[], 'Peso corporal', 'Intermedio', 'catalog/SaDOwk7.mp4', array['Ponte de pie con los pies a la anchura de los hombros.', 'Flexiona un poco las rodillas y salta hacia atrás impulsándote con los dos pies.', 'Cae suave sobre la punta de los pies, flexionando las rodillas para amortiguar.', 'Repite las repeticiones que quieras.']::text[]),
  ('0lQnxMZ', null, 'Sentadilla sissy con lastre', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Con lastre', 'Intermedio', 'catalog/0lQnxMZ.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Sujeta un peso delante del pecho con las dos manos, o apoya una barra en la parte alta de la espalda.', 'Con el pecho alto y el core apretado, baja despacio flexionando rodillas y cadera.', 'Sigue bajando hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.', 'Aguanta un momento abajo y empuja con los talones para volver a la posición inicial.']::text[]),
  ('W9pFVv1', null, 'Sentadilla al banco con barra', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/W9pFVv1.mp4', array['Coloca la barra en el rack a la altura del pecho.', 'Ponte de espaldas al rack, con los pies a la anchura de los hombros.', 'Flexiona las rodillas y baja a la sentadilla, con la espalda recta y el pecho alto.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Saca la barra del rack y da un paso atrás, con los pies a la anchura de los hombros.']::text[]),
  ('QjE2DcA', null, 'Sentadilla búlgara con subida al step', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Mancuernas', 'Intermedio', 'catalog/QjE2DcA.mp4', array['Ponte delante de un banco o step con una mancuerna en cada mano, palmas hacia el cuerpo.', 'Apoya el pie derecho en el banco o step, con toda la planta en contacto.', 'Sube al banco con el pie derecho, empujando con el talón.', 'Al subir, lleva a la vez la rodilla izquierda hacia el pecho.', 'Aguanta arriba y baja el pie izquierdo despacio al suelo, manteniendo el derecho en el banco.']::text[]),
  ('wWFspEi', null, 'Sentadilla búlgara a una pierna en multipower', 'quads', array['glutes', 'hamstrings']::text[], 'Máquina', 'Principiante', 'catalog/wWFspEi.mp4', array['Ponte delante del multipower con los pies a la anchura de los hombros.', 'Apoya un pie por detrás en un banco o step, con la punta hacia delante.', 'Agárrate a la barra del multipower para estabilizarte.', 'Flexiona la rodilla de delante y baja a la zancada, con la espalda recta.', 'Aguanta un momento abajo y empuja con el talón de delante para volver a la posición inicial.']::text[]),
  ('xAySMB0', null, 'Tabla de equilibrio', 'quads', array['calves', 'hamstrings', 'glutes']::text[], 'Peso corporal', 'Intermedio', 'catalog/xAySMB0.mp4', array['Pon la tabla de equilibrio en una superficie plana.', 'Súbete a la tabla con un pie, bien centrado.', 'Pasa el peso despacio a ese pie, con el core apretado.', 'Mantén el equilibrio aguantando la posición el tiempo que quieras.', 'Repite el ejercicio con el otro pie.']::text[]),
  ('SGY8Zui', null, 'Cargada y press con barra', 'quads', array['hamstrings', 'glutes', 'triceps']::text[], 'Barra', 'Avanzado', 'catalog/SGY8Zui.mp4', array['Ponte de pie con los pies a la anchura de los hombros y la barra en el suelo delante de ti.', 'Flexiona las rodillas e inclínate desde la cadera para bajar y agarrar la barra en pronación, con las manos algo más abiertas que los hombros.', 'Empuja con los talones y estira cadera y rodillas para despegar la barra del suelo, manteniéndola pegada al cuerpo.', 'Cuando la barra llegue a los muslos, estira la cadera de forma explosiva, encoge los hombros y tira de la barra hacia el pecho.', 'Cuando la barra llegue a la altura del pecho, métete rápido debajo y recíbela sobre los hombros, con los codos hacia delante y las palmas hacia arriba.']::text[]),
  ('r5DgrW9', null, 'Sentadilla asistida con mancuernas', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Mancuernas', 'Intermedio', 'catalog/r5DgrW9.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano a los lados.', 'Con el pecho alto y el core apretado, baja despacio flexionando las rodillas y llevando la cadera atrás.', 'Sigue bajando hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.', 'Aguanta un momento abajo y empuja con los talones para volver a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('6YUfHPL', null, 'Sentadilla sin peso', 'quads', array['hamstrings', 'glutes']::text[], 'Peso corporal', 'Intermedio', 'catalog/6YUfHPL.mp4', array['Ponte de pie con los pies a la anchura de los hombros.', 'Baja flexionando las rodillas y llevando la cadera atrás, como si fueras a sentarte.', 'Mantén el pecho alto y la espalda recta.', 'Baja hasta que los muslos queden paralelos al suelo.', 'Empuja con los talones para volver a la posición inicial.']::text[]),
  ('uKyN64F', null, 'Sentadilla a una pierna con barra', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/uKyN64F.mp4', array['Ponte de pie con los pies a la anchura de los hombros y la barra apoyada en la parte alta de la espalda.', 'Despega un pie del suelo y estíralo hacia delante, paralelo al suelo.', 'Flexiona la pierna de apoyo y baja como si fueras a sentarte, con el pecho alto y la espalda recta.', 'Baja hasta que el muslo quede paralelo al suelo y empuja con el talón para volver a la posición inicial.', 'Repite las repeticiones que quieras y cambia de pierna.']::text[]),
  ('mweqJin', null, 'Pies rápidos (variante)', 'quads', array['calves', 'hamstrings']::text[], 'Peso corporal', 'Intermedio', 'catalog/mweqJin.mp4', array['Ponte de pie con los pies a la anchura de los hombros y los brazos a los lados.', 'Empieza moviendo los pies rápido arriba y abajo, como si corrieras en el sitio.', 'Mantén el movimiento rápido y ligero, apoyándote en la punta de los pies.', 'Sigue el tiempo o las repeticiones que quieras.']::text[]),
  ('gfk9kD4', null, 'Sentadilla overhead con barra', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Barra', 'Avanzado', 'catalog/gfk9kD4.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Sujeta la barra con agarre ancho, por encima de la cabeza y con los brazos estirados del todo.', 'Aprieta el core y baja a la sentadilla, con el pecho alto y las rodillas siguiendo la línea de los pies.', 'Aguanta un momento abajo y empuja con los talones para volver a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('c8f5cSY', null, 'Aducción de cadera tumbado de lado', 'quads', array['glutes', 'hamstrings']::text[], 'Peso corporal', 'Intermedio', 'catalog/c8f5cSY.mp4', array['Túmbate de lado con las piernas estiradas y una encima de la otra.', 'Pon el brazo de abajo bajo la cabeza para apoyarte.', 'Aprieta los aductores y sube la pierna de arriba todo lo que puedas sin girar la cadera ni echarte atrás.', 'Aguanta un momento arriba y baja la pierna despacio a la posición inicial.', 'Repite las repeticiones que quieras y cambia de lado.']::text[]),
  ('W31mMjd', null, 'Sentadilla lateral abierta con barra', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/W31mMjd.mp4', array['Ponte de pie con los pies más abiertos que los hombros y las puntas algo hacia fuera.', 'Apoya la barra en la parte alta de la espalda, sobre el trapecio.', 'Aprieta el core y mantén el pecho alto mientras bajas a la sentadilla, flexionando rodillas y cadera.', 'Al bajar, abre las rodillas hacia fuera y mantén el peso en los talones.', 'Baja hasta que los muslos queden paralelos al suelo y empuja con los talones para volver a la posición inicial.']::text[]),
  ('VO2qeJg', null, 'Aducción de cadera en plancha lateral', 'obliques', array['glutes', 'quads']::text[], 'Peso corporal', 'Intermedio', 'catalog/VO2qeJg.mp4', array['Empieza tumbado de lado con las piernas estiradas y una encima de la otra.', 'Apóyate sobre el antebrazo, con el codo justo debajo del hombro.', 'Aprieta el core y despega la cadera del suelo, dejando el cuerpo en línea recta de la cabeza a los pies.', 'Manteniendo la plancha lateral, sube la pierna de arriba hacia el techo, estirada.', 'Baja la pierna despacio a la posición inicial.']::text[]),
  ('gGNQmVt', null, 'Sentadilla búlgara a una pierna con barra', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/gGNQmVt.mp4', array['Ponte de pie con los pies a la anchura de los hombros y la barra apoyada en la parte alta de la espalda.', 'Da un paso largo adelante con una pierna, con el tronco erguido.', 'Baja flexionando la rodilla y la cadera de delante, con la pierna de atrás estirada.', 'Sigue bajando hasta que el muslo de delante quede paralelo al suelo.', 'Aguanta un momento y empuja con el talón adelantado para volver a la posición inicial.']::text[]),
  ('xdYPUtE', null, 'Sentadilla sissy', 'quads', array['calves', 'glutes']::text[], 'Peso corporal', 'Intermedio', 'catalog/xdYPUtE.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Agárrate a algo estable si necesitas equilibrio.', 'Baja despacio flexionando las rodillas y echándote atrás, con el tronco erguido.', 'Sigue bajando hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.', 'Aguanta un momento y empuja con los talones para volver a la posición inicial.']::text[]),
  ('HBYyX94', null, 'Sentadilla búlgara con barra (variante)', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/HBYyX94.mp4', array['Empieza de pie con los pies a la anchura de los hombros y la barra apoyada en la parte alta de la espalda.', 'Da un paso largo adelante con el pie derecho, con el tronco erguido.', 'Baja flexionando rodillas y cadera hasta que el muslo derecho quede paralelo al suelo.', 'Aguanta un momento y empuja con el talón derecho para volver a la posición inicial.', 'Repite con la pierna izquierda delante las repeticiones que quieras.']::text[]),
  ('9E25EOx', null, 'Sentadillas búlgaras', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Peso corporal', 'Intermedio', 'catalog/9E25EOx.mp4', array['Ponte de pie con los pies a la anchura de los hombros.', 'Da un paso adelante con un pie y déjalo a unos sesenta centímetros del otro.', 'Baja flexionando rodillas y cadera, con la espalda recta.', 'Sigue bajando hasta que el muslo de delante quede paralelo al suelo y la rodilla de atrás justo encima de él.', 'Aguanta un momento y empuja con el talón adelantado para volver a la posición inicial.']::text[]),
  ('oR7O9LW', null, 'Sentadilla de rodillas con barra', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/oR7O9LW.mp4', array['Empieza de rodillas en el suelo, con las rodillas a la anchura de la cadera y las puntas hacia delante.', 'Apoya la barra sobre los hombros, agarrándola en pronación con las manos algo más abiertas que los hombros.', 'Aprieta el core y mantén el pecho alto mientras bajas despacio flexionando las rodillas, con la espalda recta.', 'Sigue bajando hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.', 'Aguanta un momento abajo y empuja con los talones para volver a la posición inicial.']::text[]),
  ('QChZi3x', null, 'Sentadilla con extensión sobre la cabeza', 'quads', array['glutes', 'hamstrings']::text[], 'Peso corporal', 'Intermedio', 'catalog/QChZi3x.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Baja a la sentadilla flexionando las rodillas y llevando la cadera atrás.', 'Al subir de la sentadilla, estira los brazos por encima de la cabeza hacia el techo.', 'Vuelve a la posición inicial bajando los brazos y flexionando las rodillas para volver a la sentadilla.', 'Repite las repeticiones que quieras.']::text[]),
  ('RYcV1kH', null, 'Sentadilla con salto y zancada atrás', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/RYcV1kH.mp4', array['Empieza de pie con los pies a la anchura de los hombros y la barra apoyada en la parte alta de la espalda.', 'Baja a la sentadilla flexionando las rodillas y llevando la cadera atrás.', 'Explota hacia arriba, saltando todo lo alto que puedas.', 'Cae suave y da un paso atrás con una pierna hacia una zancada inversa.', 'Baja hasta que el muslo de delante quede paralelo al suelo, con la espalda recta.']::text[]),
  ('5BZHW9s', null, 'Sentadilla con extensión y giro', 'quads', array['glutes', 'hamstrings']::text[], 'Peso corporal', 'Intermedio', 'catalog/5BZHW9s.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Baja a la sentadilla flexionando las rodillas y llevando la cadera atrás.', 'Al subir de la sentadilla, sube los brazos por encima de la cabeza y gira el tronco hacia un lado.', 'Vuelve a la posición inicial y repite la sentadilla, girando el tronco al lado contrario.', 'Sigue alternando lados en cada repetición.']::text[]),
  ('s7HX1BY', null, 'Sentadilla con barra y piernas abiertas', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/s7HX1BY.mp4', array['Ponte de pie con los pies más abiertos que los hombros y las puntas algo hacia fuera.', 'Apoya la barra en la parte alta de la espalda, sobre el trapecio o el deltoides posterior.', 'Aprieta el core y mantén el pecho alto mientras bajas a la sentadilla, llevando la cadera atrás y flexionando las rodillas.', 'Baja hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.', 'Aguanta un momento abajo y empuja con los talones para volver a la posición inicial.']::text[]),
  ('QpXqiq8', null, 'Sentadilla búlgara en suspensión', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Peso corporal', 'Intermedio', 'catalog/QpXqiq8.mp4', array['Ponte de espaldas a unas cintas de suspensión, con los pies a la anchura de los hombros.', 'Estira una pierna hacia delante y apoya el empeine en el estribo de las cintas.', 'Flexiona la pierna de apoyo y baja a la zancada, con el pecho alto y la rodilla en línea con la punta del pie.', 'Empuja con el talón para volver a la posición inicial.', 'Repite las repeticiones que quieras y cambia de pierna.']::text[]),
  ('dG5Smob', null, 'Tirón de arrancada', 'quads', array['hamstrings', 'glutes', 'calves']::text[], 'Barra', 'Avanzado', 'catalog/dG5Smob.mp4', array['Ponte de pie con los pies a la anchura de los hombros y la barra en el suelo delante de ti.', 'Flexiona las rodillas e inclínate desde la cadera para bajar a la sentadilla, agarrando la barra en pronación.', 'Mantén la espalda recta y el pecho alto mientras empujas con los talones para despegar la barra del suelo, estirando cadera y rodillas.', 'Cuando la barra llegue a la cadera, tira de ella hacia arriba de forma explosiva, encogiendo los hombros y llevando los codos altos y hacia los lados.', 'Cuando la barra llegue a su punto más alto, métete rápido debajo cayendo en sentadilla profunda.']::text[]),
  ('IMRsOCn', null, 'Squat jerk', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/IMRsOCn.mp4', array['Empieza con la barra apoyada en los hombros y los pies a la anchura de los hombros.', 'Baja a la sentadilla, con el pecho alto y las rodillas siguiendo la línea de los pies.', 'Al llegar abajo, empuja con las piernas de forma explosiva y lanza la barra por encima de la cabeza.', 'Cuando la barra llegue arriba del todo, cae rápido en tijera, con un pie delante y otro detrás.', 'Recibe la barra por encima de la cabeza con los brazos estirados del todo y la rodilla de atrás rozando el suelo.']::text[]),
  ('Yza7XrQ', null, 'Curl de bíceps alterno con barra', 'biceps', array['forearm']::text[], 'Barra', 'Principiante', 'catalog/Yza7XrQ.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una barra en cada mano, palmas hacia delante.', 'Mantén los brazos quietos y suelta el aire mientras subes el peso contrayendo el bíceps.', 'Sigue subiendo las barras hasta contraer el bíceps del todo, con las barras a la altura de los hombros.', 'Aguanta un instante en la contracción apretando el bíceps.', 'Coge aire mientras bajas las barras despacio a la posición inicial.']::text[]),
  ('zILLZ98', null, 'Curl de bíceps en multipower', 'biceps', array['forearm']::text[], 'Máquina', 'Principiante', 'catalog/zILLZ98.mp4', array['Ajusta la barra del multipower a la altura de la cintura.', 'Ponte de pie frente al multipower con los pies a la anchura de los hombros.', 'Agarra la barra en supinación, con las manos algo más abiertas que los hombros.', 'Mantén los codos pegados al cuerpo y los brazos quietos.', 'Suelta el aire y sube la barra hacia los hombros contrayendo el bíceps.']::text[]),
  ('sJFIDIp', null, 'Curl concentrado apoyado en la pierna', 'biceps', array['forearm']::text[], 'Peso corporal', 'Principiante', 'catalog/sJFIDIp.mp4', array['Siéntate en un banco con las piernas abiertas y los pies apoyados en el suelo.', 'Sujeta una mancuerna en una mano y apoya el codo en la cara interna del muslo, justo encima de la rodilla.', 'Con la palma hacia arriba, sube la mancuerna hacia el hombro manteniendo el brazo quieto.', 'Aprieta el bíceps arriba y baja la mancuerna despacio a la posición inicial.', 'Repite las repeticiones que quieras y cambia de brazo.']::text[]),
  ('M5Y7GPg', null, 'Curl de pie con lastre', 'biceps', array['forearm']::text[], 'Con lastre', 'Principiante', 'catalog/M5Y7GPg.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano, con las palmas hacia delante.', 'Mantén los codos pegados al cuerpo y suelta el aire mientras subes el peso a la altura de los hombros.', 'Aguanta un momento arriba y coge aire mientras bajas el peso despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('aee2Fcj', null, 'Curl de bíceps con barra y arm blaster', 'biceps', array['forearm']::text[], 'Barra', 'Principiante', 'catalog/aee2Fcj.mp4', array['Ponte de pie con los pies a la anchura de los hombros y sujeta la barra en supinación, con las palmas hacia arriba.', 'Apoya los brazos contra el arm blaster, con los codos pegados al cuerpo.', 'Con los brazos quietos, suelta el aire y sube el peso contrayendo el bíceps.', 'Sigue subiendo la barra hasta contraer el bíceps del todo, con la barra a la altura de los hombros.', 'Aguanta un instante en la contracción apretando el bíceps.']::text[]),
  ('fy7Tgy4', null, 'Curl predicador martillo alterno con mancuernas', 'biceps', array['forearm']::text[], 'Mancuernas', 'Principiante', 'catalog/fy7Tgy4.mp4', array['Siéntate en el banco predicador con una mancuerna en cada mano, palmas hacia el cuerpo y brazos estirados del todo.', 'Mantén los brazos quietos y suelta el aire mientras subes el peso contrayendo el bíceps.', 'Sigue subiendo las mancuernas hasta contraer el bíceps del todo, con las mancuernas a la altura de los hombros.', 'Aguanta un instante en la contracción apretando el bíceps.', 'Coge aire y empieza a bajar las mancuernas despacio a la posición inicial.']::text[]),
  ('NvfE43H', null, 'Curl concentrado en polea', 'biceps', array['forearm']::text[], 'Polea', 'Principiante', 'catalog/NvfE43H.mp4', array['Siéntate en un banco o una silla con los pies apoyados en el suelo y las rodillas algo flexionadas.', 'Sujeta el asa en supinación y apoya el codo contra la cara interna del muslo.', 'Con el brazo quieto, suelta el aire y sube el asa hacia el hombro contrayendo el bíceps.', 'Aguanta un momento arriba, coge aire y baja el asa despacio a la posición inicial.', 'Repite las repeticiones que quieras y cambia de brazo.']::text[]),
  ('50BETrz', null, 'Dominadas cerradas para bíceps', 'biceps', array['forearm']::text[], 'Peso corporal', 'Intermedio', 'catalog/50BETrz.mp4', array['Cuélgate de la barra en supinación, con las manos a la anchura de los hombros.', 'Aprieta el core y sube hacia la barra, tirando sobre todo con el bíceps.', 'Aguanta un momento arriba y baja despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('IENzBdA', null, 'Curl drag con barra', 'biceps', array['forearm']::text[], 'Barra', 'Principiante', 'catalog/IENzBdA.mp4', array['Ponte de pie con los pies a la anchura de los hombros y sujeta la barra en supinación, con las palmas hacia arriba.', 'Deja la barra colgando con los brazos estirados delante de los muslos.', 'Con los brazos quietos, sube la barra hacia el pecho contrayendo el bíceps.', 'Aguanta un momento arriba y baja la barra despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('NlfIbzq', null, 'Curl predicador alterno con mancuernas', 'biceps', array['forearm']::text[], 'Mancuernas', 'Principiante', 'catalog/NlfIbzq.mp4', array['Siéntate en el banco predicador con una mancuerna en cada mano, palmas hacia arriba.', 'Apoya los brazos en la almohadilla del banco predicador, dejándolos estirarse del todo.', 'Con los brazos quietos, suelta el aire y sube la mancuerna de la mano derecha contrayendo el bíceps.', 'Sigue subiendo la mancuerna hasta contraer el bíceps del todo, con la mancuerna a la altura del hombro.', 'Aguanta un momento, coge aire y baja la mancuerna despacio a la posición inicial.']::text[]),
  ('G08RZcQ', null, 'Curl de bíceps en polea', 'biceps', array['forearm']::text[], 'Polea', 'Principiante', 'catalog/G08RZcQ.mp4', array['Ponte de pie frente a la polea con los pies a la anchura de los hombros.', 'Agarra el accesorio de la polea en supinación, con las palmas hacia arriba.', 'Mantén los codos pegados al cuerpo y los brazos quietos.', 'Suelta el aire y sube el accesorio hacia los hombros contrayendo el bíceps.', 'Aguanta un momento arriba apretando el bíceps.']::text[]),
  ('guT8YnS', null, 'Dominadas para bíceps', 'biceps', array['forearm']::text[], 'Peso corporal', 'Intermedio', 'catalog/guT8YnS.mp4', array['Cuélgate de la barra en pronación, con las manos a la anchura de los hombros.', 'Aprieta el core y sube flexionando los codos, llevando el pecho hacia la barra.', 'Aguanta arriba y baja despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('SYJ4Bkt', null, 'Curl predicador tumbado con barra', 'biceps', array['forearm']::text[], 'Barra', 'Principiante', 'catalog/SYJ4Bkt.mp4', array['Siéntate en el banco predicador con el pecho contra la almohadilla y los brazos estirados sobre el borde, sujetando la barra en supinación.', 'Con los brazos quietos, suelta el aire y sube el peso contrayendo el bíceps.', 'Sigue subiendo la barra hasta contraer el bíceps del todo, con la barra a la altura de los hombros.', 'Aguanta un instante en la contracción apretando el bíceps.', 'Coge aire y empieza a bajar la barra despacio a la posición inicial.']::text[]),
  ('6em2Dxj', null, 'Curl martillo sentado alterno con mancuernas', 'biceps', array['forearm']::text[], 'Mancuernas', 'Principiante', 'catalog/6em2Dxj.mp4', array['Siéntate en un banco con una mancuerna en cada mano, palmas hacia el cuerpo y brazos estirados hacia abajo.', 'Mantén la espalda recta y los codos pegados al cuerpo.', 'Suelta el aire y sube la mancuerna de la mano derecha hacia el hombro, con el brazo quieto.', 'Sigue subiendo la mancuerna hasta contraer el bíceps del todo, con la mancuerna a la altura del hombro.', 'Aguanta un instante, coge aire y baja la mancuerna despacio a la posición inicial.']::text[]),
  ('dXz8zjF', null, 'Curl drag en polea', 'biceps', array['forearm']::text[], 'Polea', 'Principiante', 'catalog/dXz8zjF.mp4', array['Ponte de pie frente a una polea con los pies a la anchura de los hombros.', 'Agarra el accesorio en supinación, palmas hacia arriba y brazos estirados del todo.', 'Con los brazos quietos, suelta el aire y sube el accesorio hacia los hombros contrayendo el bíceps.', 'Aguanta un momento arriba apretando el bíceps.', 'Coge aire y baja el accesorio despacio a la posición inicial, estirando los brazos del todo.']::text[]),
  ('gscGLOU', null, 'Curl de bíceps tumbado de lado sin peso', 'biceps', array['forearm']::text[], 'Peso corporal', 'Principiante', 'catalog/gscGLOU.mp4', array['Túmbate de lado con las piernas estiradas y la cabeza apoyada en el brazo.', 'Mantén el brazo pegado al costado y flexiona el codo para llevar el antebrazo hacia el hombro.', 'Aguanta un momento arriba y baja el antebrazo despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('WLvTAv5', null, 'Curl inclinado boca abajo con barra', 'biceps', array['forearm']::text[], 'Barra', 'Principiante', 'catalog/WLvTAv5.mp4', array['Coloca un banco inclinado a 45 grados.', 'Túmbate boca abajo en el banco, con el pecho y el abdomen apoyados.', 'Sujeta la barra en supinación, a la anchura de los hombros.', 'Estira los brazos del todo, dejando la barra colgando hacia el suelo.', 'Con los brazos quietos, suelta el aire y sube el peso contrayendo el bíceps.']::text[]),
  ('Zwiw7XR', null, 'Curl de bíceps alterno con pierna elevada en fitball', 'biceps', array['forearm']::text[], 'Mancuernas', 'Principiante', 'catalog/Zwiw7XR.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano, con las palmas hacia delante.', 'Pon un fitball detrás de ti y apoya un pie encima, manteniendo el equilibrio.', 'Con los brazos estirados del todo y los codos pegados al cuerpo, sube una mancuerna hacia el hombro manteniendo el brazo quieto.', 'Baja la mancuerna a la posición inicial y repite con el otro brazo.', 'Sigue alternando brazos durante las repeticiones que quieras.']::text[]),
  ('HPlPoQA', null, 'Curl martillo en polea con cuerda', 'biceps', array['forearm']::text[], 'Polea', 'Principiante', 'catalog/HPlPoQA.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las rodillas algo flexionadas.', 'Sujeta la cuerda de la polea con las palmas enfrentadas y los brazos estirados del todo.', 'Con los brazos quietos, suelta el aire y sube el peso contrayendo el bíceps.', 'Sigue subiendo la cuerda hasta contraer el bíceps del todo, con la cuerda a la altura de los hombros.', 'Aguanta un instante en la contracción apretando el bíceps.']::text[]),
  ('xNrS20v', null, 'Curl inverso con barra', 'biceps', array['forearm']::text[], 'Barra', 'Principiante', 'catalog/xNrS20v.mp4', array['Ponte de pie con los pies a la anchura de los hombros y sujeta la barra en pronación, con las palmas hacia abajo.', 'Mantén los brazos quietos y suelta el aire mientras subes la barra contrayendo el bíceps.', 'Sigue subiendo la barra hasta contraer el bíceps del todo, con la barra a la altura de los hombros.', 'Aguanta un instante en la contracción apretando el bíceps.', 'Coge aire mientras bajas la barra despacio a la posición inicial, con los brazos quietos.']::text[]),
  ('J74XlNf', null, 'Curl de bíceps sentado alterno en fitball', 'biceps', array['forearm']::text[], 'Mancuernas', 'Principiante', 'catalog/J74XlNf.mp4', array['Siéntate en un fitball con los pies apoyados en el suelo y la espalda recta.', 'Sujeta una mancuerna en cada mano con las palmas hacia delante y los brazos estirados del todo.', 'Con los brazos quietos, suelta el aire y sube una mancuerna girando el antebrazo hasta que la palma mire al hombro.', 'Coge aire y baja la mancuerna despacio a la posición inicial.', 'Repite el curl con el otro brazo.']::text[]),
  ('otqIxU4', null, 'Curl de bíceps tumbado en polea', 'biceps', array['forearm']::text[], 'Polea', 'Principiante', 'catalog/otqIxU4.mp4', array['Engancha una barra recta a una polea baja.', 'Túmbate boca arriba en un banco plano con los pies apoyados en el suelo.', 'Agarra la barra en supinación, con las manos a la anchura de los hombros.', 'Estira los brazos del todo, con los codos pegados al cuerpo.', 'Con los brazos quietos, suelta el aire y sube la barra hacia los hombros.']::text[]),
  ('4LIG9xr', null, 'Curl predicador inverso con barra', 'biceps', array['forearm']::text[], 'Barra', 'Principiante', 'catalog/4LIG9xr.mp4', array['Siéntate en el banco predicador con el pecho contra la almohadilla y los brazos estirados hacia abajo, sujetando la barra en pronación.', 'Con los brazos quietos, suelta el aire y sube la barra contrayendo el bíceps.', 'Sigue subiendo la barra hasta contraer el bíceps del todo, con la barra a la altura de los hombros.', 'Aguanta un instante en la contracción apretando el bíceps.', 'Coge aire y baja la barra despacio a la posición inicial.']::text[]),
  ('1VpF8db', null, 'Curl de bíceps con zancada y giro', 'biceps', array['forearm']::text[], 'Mancuernas', 'Principiante', 'catalog/1VpF8db.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano, con las palmas hacia delante.', 'Da un paso adelante con el pie derecho, flexionando esa rodilla y bajando a la zancada.', 'Mientras haces la zancada, sube las mancuernas hacia los hombros con los codos pegados al cuerpo.', 'Abajo del todo, gira el tronco a la derecha, como si lanzaras una bola de bolos.', 'Invierte el movimiento, vuelve con el pie derecho a la posición inicial y baja las mancuernas.']::text[]),
  ('61GrD55', null, 'Curl tumbado en polea con agarre cerrado', 'biceps', array['forearm']::text[], 'Polea', 'Principiante', 'catalog/61GrD55.mp4', array['Engancha una barra recta a una polea baja.', 'Túmbate boca arriba en un banco plano con los pies apoyados en el suelo.', 'Agarra la barra en supinación, con las manos a la anchura de los hombros.', 'Estira los brazos del todo, con los codos pegados al cuerpo.', 'Con los brazos quietos, sube la barra hacia el pecho contrayendo el bíceps.']::text[]),
  ('1V1gj1u', null, 'Curl concentrado sentado con barra y agarre cerrado', 'biceps', array['forearm']::text[], 'Barra', 'Principiante', 'catalog/1V1gj1u.mp4', array['Siéntate en un banco con los pies apoyados en el suelo y sujeta la barra en supinación, con las manos a la anchura de los hombros.', 'Apoya los brazos contra la cara interna de los muslos, justo encima de las rodillas, y deja la barra colgando por delante.', 'Con los brazos quietos, suelta el aire y sube la barra hacia los hombros contrayendo el bíceps.', 'Aguanta un instante en la contracción, coge aire y baja la barra despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('2NImIAG', null, 'Curl de bíceps en fitball con pierna elevada', 'biceps', array['forearm']::text[], 'Mancuernas', 'Principiante', 'catalog/2NImIAG.mp4', array['Siéntate en un fitball con los pies apoyados en el suelo y la espalda recta.', 'Sujeta una mancuerna en cada mano con las palmas hacia delante y los brazos estirados del todo.', 'Sube las mancuernas despacio hacia los hombros, con los codos pegados al cuerpo.', 'Aguanta un momento arriba y baja las mancuernas despacio a la posición inicial.', 'Mientras haces el curl, levanta una pierna del suelo y mantenla en el aire durante todo el ejercicio.']::text[]),
  ('4dUn2iv', null, 'Curl de pie con barra y agarre cerrado', 'biceps', array['forearm']::text[], 'Barra', 'Principiante', 'catalog/4dUn2iv.mp4', array['Ponte de pie con los pies a la anchura de los hombros y sujeta la barra en supinación, con las manos juntas.', 'Mantén los codos pegados al cuerpo y los brazos quietos durante todo el movimiento.', 'Suelta el aire mientras subes el peso contrayendo el bíceps. Sigue subiendo la barra hasta contraerlo del todo, con la barra a la altura de los hombros.', 'Aguanta un instante en la contracción apretando el bíceps.', 'Coge aire mientras devuelves la barra despacio a la posición inicial.']::text[]),
  ('J6Dx1Mu', null, 'Press de banca con barra y agarre cerrado', 'triceps', '{}', 'Barra', 'Intermedio', 'catalog/J6Dx1Mu.mp4', array['Túmbate en el banco con los pies apoyados en el suelo y la espalda pegada al banco.', 'Agarra la barra cerrado, algo más estrecho que la anchura de los hombros.', 'Saca la barra del soporte y bájala despacio hacia el pecho, con los codos pegados al cuerpo.', 'Aguanta un momento cuando la barra toque el pecho.', 'Empuja la barra de vuelta a la posición inicial estirando los brazos del todo.']::text[]),
  ('7jGOBF3', null, 'Press con mancuernas y agarre cerrado', 'triceps', '{}', 'Mancuernas', 'Intermedio', 'catalog/7jGOBF3.mp4', array['Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos.', 'Ayúdate de los muslos para subir las mancuernas de una en una y sujetarlas delante de ti, a la anchura de los hombros.', 'Ya a esa altura, gira las muñecas hacia delante para que las palmas miren hacia fuera. Esa es la posición inicial.', 'Coge aire y baja las mancuernas despacio a los lados, hasta la altura del pecho.', 'Suelta el aire y sube las mancuernas con el tríceps hasta la posición inicial. Tira solo con el tríceps, sin ayudarte de antebrazos ni bíceps.']::text[]),
  ('Gchi5Tr', null, 'Extensión de tríceps alterna en polea', 'triceps', '{}', 'Polea', 'Principiante', 'catalog/Gchi5Tr.mp4', array['Ponte de pie frente a la polea con los pies a la anchura de los hombros.', 'Sujeta el asa con la mano derecha y sube el brazo hasta dejarlo paralelo al suelo, con el codo a 90 grados.', 'Mantén el brazo quieto y estira el antebrazo hacia atrás hasta extenderlo del todo.', 'Aguanta un momento y vuelve despacio a la posición inicial.', 'Repite con el brazo izquierdo.']::text[]),
  ('J60bN17', null, 'Fondos de tríceps asistidos (de rodillas)', 'triceps', '{}', 'Máquina', 'Principiante', 'catalog/J60bN17.mp4', array['Ajusta la máquina al peso y la altura que quieras.', 'Ponte de rodillas en la almohadilla frente a la máquina, agarrando las asas.', 'Baja el cuerpo flexionando los codos, con la espalda recta y pegada a la máquina.', 'Aguanta un momento abajo y empuja para volver a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('RrLske5', null, 'Fondos en banco (rodillas flexionadas)', 'triceps', '{}', 'Peso corporal', 'Intermedio', 'catalog/RrLske5.mp4', array['Siéntate en el borde de un banco o una silla agarrando el borde junto a la cadera.', 'Desliza el culo fuera del banco y estira las piernas por delante, con los talones en el suelo.', 'Flexiona los codos y baja el cuerpo hacia el suelo, con la espalda pegada al banco.', 'Aguanta un momento abajo y empuja para volver a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('MU9HnE7', null, 'Fondos en banco con lastre', 'triceps', '{}', 'Con lastre', 'Intermedio', 'catalog/MU9HnE7.mp4', array['Siéntate en un banco agarrando el borde, con los dedos hacia delante.', 'Desliza el culo fuera del banco y aguanta el peso con las manos.', 'Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.', 'Empuja para volver a la posición inicial estirando los brazos.', 'Repite las repeticiones que quieras.']::text[]),
  ('LMGXZn8', null, 'Press declinado a la frente con barra y agarre cerrado', 'triceps', '{}', 'Barra', 'Intermedio', 'catalog/LMGXZn8.mp4', array['Túmbate en un banco declinado con la cabeza más baja que los pies y sujeta la barra con agarre cerrado.', 'Baja la barra hacia la frente flexionando los codos, con los brazos quietos.', 'Aguanta un momento y estira los brazos para devolver la barra a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('Db7eEgw', null, 'Extensión concentrada en polea (sobre la rodilla)', 'triceps', array['forearm']::text[], 'Polea', 'Principiante', 'catalog/Db7eEgw.mp4', array['Siéntate en un banco o una silla con las rodillas flexionadas y los pies apoyados.', 'Sujeta el asa con la mano derecha y apoya el codo en la cara interna de la rodilla derecha.', 'Estira el brazo del todo, con el codo quieto y pegado a la rodilla.', 'Aguanta un momento arriba y baja el brazo despacio a la posición inicial.', 'Repite las repeticiones que quieras y cambia de lado.']::text[]),
