  ('OTgkHwR', null, 'Extensión de tríceps declinada con mancuernas', 'triceps', '{}', 'Mancuernas', 'Principiante', 'catalog/OTgkHwR.mp4', array['Túmbate en un banco declinado con la cabeza más baja que los pies y una mancuerna en cada mano, palmas enfrentadas.', 'Estira los brazos del todo, con los codos pegados a la cabeza.', 'Baja las mancuernas despacio por detrás de la cabeza flexionando los codos.', 'Aguanta un momento y sube las mancuernas a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
