  ('yB9SvIF', null, 'Press declinado con agarre cerrado en multipower', 'triceps', '{}', 'Máquina', 'Principiante', 'catalog/yB9SvIF.mp4', array['Pon el banco del multipower en posición declinada.', 'Túmbate en el banco con los pies bien plantados en el suelo.', 'Agarra la barra cerrado, algo más estrecho que la anchura de los hombros.', 'Saca la barra del soporte y bájala despacio hacia el pecho, con los codos pegados al cuerpo.', 'Aguanta un momento con la barra justo encima del pecho.']::text[]),
