  ('x6KpKpq', null, 'Flexiones con agarre cerrado', 'triceps', '{}', 'Peso corporal', 'Intermedio', 'catalog/x6KpKpq.mp4', array['Empieza en plancha alta con las manos juntas, justo debajo de los hombros.', 'Aprieta el core y baja el cuerpo hacia el suelo, con los codos pegados al cuerpo.', 'Empuja con las palmas para estirar los brazos y volver a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('yg8Totb', null, 'Extensión de tríceps tras nuca con barra', 'triceps', '{}', 'Barra', 'Principiante', 'catalog/yg8Totb.mp4', array['Túmbate en el banco con los pies apoyados en el suelo y la cabeza al final del banco.', 'Sujeta la barra en pronación, con las manos a la anchura de los hombros, y estira los brazos encima del pecho.', 'Con los brazos quietos, baja la barra despacio por detrás de la cabeza flexionando los codos.', 'Aguanta un momento y estira los brazos de vuelta a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('wkgnGfb', null, 'Press martillo inclinado en fitball', 'triceps', '{}', 'Mancuernas', 'Intermedio', 'catalog/wkgnGfb.mp4', array['Siéntate en un fitball con una mancuerna en cada mano, palmas enfrentadas.', 'Camina con los pies hacia delante y deslízate por el balón hasta apoyar cabeza, cuello y parte alta de la espalda.', 'Sujeta las mancuernas a la altura de los hombros, con los codos flexionados y abiertos.', 'Empuja las mancuernas hacia arriba y algo hacia dentro, con las palmas enfrentadas.', 'Estira los brazos del todo, apretando el tríceps arriba.']::text[]),
  ('qi996YS', null, 'Sentadilla frontal con agarre de cargada', 'glutes', array['hamstrings', 'calves']::text[], 'Barra', 'Avanzado', 'catalog/qi996YS.mp4', array['Empieza de pie con los pies a la anchura de los hombros y la barra apoyada en la parte alta del pecho, con los codos hacia delante.', 'Baja flexionando las rodillas y llevando la cadera atrás, como si fueras a sentarte.', 'Mantén el pecho alto y la espalda recta al bajar, sin que las rodillas pasen de las puntas de los pies.', 'Sigue bajando hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.', 'Aguanta un momento abajo y empuja con los talones para subir, estirando cadera y rodillas.']::text[]),
  ('mnzcrIB', null, 'Sentadilla al banco con mancuernas', 'glutes', array['hamstrings', 'calves']::text[], 'Mancuernas', 'Intermedio', 'catalog/mnzcrIB.mp4', array['Deja una mancuerna en el suelo delante de un banco.', 'Ponte de espaldas al banco con los pies a la anchura de los hombros.', 'Flexiona rodillas y cadera para bajar hacia el banco, con el pecho alto y la espalda recta.', 'Cuando los glúteos toquen el banco, empuja con los talones para volver a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('eGDudUV', null, 'Peso muerto en polea', 'glutes', array['hamstrings']::text[], 'Polea', 'Avanzado', 'catalog/eGDudUV.mp4', array['Ponte de pie frente a la polea con los pies a la anchura de los hombros.', 'Flexiona cadera y rodillas, bajando el tronco hasta dejar la espalda paralela al suelo.', 'Agarra las asas en pronación, con los brazos estirados y los hombros atrás.', 'Aprieta glúteos e isquios para subir las asas, estirando la cadera hasta quedar erguido.', 'Aguanta un momento arriba y baja las asas despacio a la posición inicial.']::text[]),
  ('1bQkKZK', null, 'Buenos días con rodilla flexionada en multipower', 'glutes', array['hamstrings']::text[], 'Máquina', 'Principiante', 'catalog/1bQkKZK.mp4', array['Empieza de pie con los pies a la anchura de los hombros y las puntas hacia delante.', 'Apoya la barra en la parte alta de la espalda, sobre el trapecio.', 'Flexiona un poco las rodillas e inclínate hacia delante desde la cadera, con la espalda recta.', 'Baja el tronco hasta dejarlo paralelo al suelo, notando el estiramiento en los isquios.', 'Aprieta glúteos e isquios para subir el tronco a la posición inicial.']::text[]),
  ('RtyAsy1', null, 'Toque de puntas circular con brazos abiertos', 'glutes', array['hamstrings', 'calves']::text[], 'Peso corporal', 'Intermedio', 'catalog/RtyAsy1.mp4', array['Ponte de pie con los pies a la anchura de los hombros y los brazos abiertos a los lados.', 'Con las piernas estiradas, inclínate hacia delante y baja la mano derecha hacia las puntas de los pies.', 'Al bajar, sube a la vez la pierna izquierda estirada por detrás, manteniendo el equilibrio.', 'Vuelve a la posición inicial y repite con la mano izquierda hacia los pies y la pierna derecha por detrás.', 'Sigue alternando lados durante las repeticiones que quieras.']::text[]),
  ('GWoKnIm', null, 'Sentadillas cosacas con lastre', 'glutes', array['hamstrings', 'calves']::text[], 'Con lastre', 'Intermedio', 'catalog/GWoKnIm.mp4', array['Ponte de pie con los pies más abiertos que los hombros y las puntas algo hacia fuera.', 'Sujeta un peso delante del pecho con las dos manos.', 'Pasa el peso a un lado y baja flexionando esa rodilla, con la otra pierna estirada.', 'Baja todo lo que puedas manteniendo el equilibrio y el pecho alto.', 'Empuja con el talón de la pierna flexionada para volver a la posición inicial.']::text[]),
  ('IeTIEqg', null, 'Sentadilla frontal al pecho con barra', 'glutes', array['hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/IeTIEqg.mp4', array['Empieza de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Sujeta la barra delante del pecho con las manos a la anchura de los hombros y los codos hacia delante.', 'Aprieta el core y mantén el pecho alto mientras bajas a la sentadilla, llevando la cadera atrás y flexionando las rodillas.', 'Baja hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.', 'Aguanta un momento abajo y empuja con los talones para volver a la posición inicial.']::text[]),
  ('7Hg55JG', null, 'Cargada con mancuernas', 'glutes', array['hamstrings', 'calves']::text[], 'Mancuernas', 'Avanzado', 'catalog/7Hg55JG.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano en pronación.', 'Flexiona las rodillas y baja la cadera a la sentadilla, con la espalda recta y el pecho alto.', 'Estira cadera y rodillas de forma explosiva, empujando con los talones para saltar.', 'Al saltar, encoge los hombros y sube las mancuernas hacia ellos, pegadas al cuerpo.', 'Recibe las mancuernas a la altura de los hombros, con los codos hacia delante y las palmas hacia arriba.']::text[]),
  ('Kpajagk', null, 'Extensión de cadera de pie en polea', 'glutes', array['hamstrings']::text[], 'Polea', 'Principiante', 'catalog/Kpajagk.mp4', array['Engancha un cable a la polea baja y ponte de espaldas a la máquina.', 'Pásate el cable por el tobillo y ponte con los pies a la anchura de los hombros.', 'Mantén el core apretado y la espalda recta durante todo el ejercicio.', 'Estira la pierna despacio hacia atrás, apretando el glúteo arriba.', 'Aguanta un momento y vuelve a la posición inicial.']::text[]),
  ('UfePqpx', null, 'Peso muerto en multipower', 'glutes', array['hamstrings']::text[], 'Máquina', 'Avanzado', 'catalog/UfePqpx.mp4', array['Coloca la barra del multipower a la altura de la cadera.', 'Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Flexiona cadera y rodillas, con la espalda recta y el pecho alto, y agarra la barra en pronación algo más abierto que los hombros.', 'Aprieta el core y sube la barra estirando cadera y rodillas, manteniéndola pegada al cuerpo.', 'Ponte erguido, estirando cadera y rodillas del todo.']::text[]),
  ('BbfB8Gb', null, 'Toque de puntas básico', 'glutes', array['hamstrings', 'calves']::text[], 'Peso corporal', 'Intermedio', 'catalog/BbfB8Gb.mp4', array['Ponte de pie con los pies a la anchura de los hombros y los brazos a los lados.', 'Inclínate hacia delante, con la espalda recta y las rodillas algo flexionadas.', 'Baja las manos hacia las puntas de los pies, con las piernas lo más estiradas posible.', 'Aguanta un momento abajo y vuelve despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('5WiFcYk', null, 'Zancada con balanceo y lastre', 'glutes', array['hamstrings', 'calves']::text[], 'Con lastre', 'Intermedio', 'catalog/5WiFcYk.mp4', array['Ponte de pie con los pies a la anchura de los hombros y un peso en cada mano.', 'Da un paso adelante con el pie derecho y baja a la zancada.', 'Mientras haces la zancada, balancea los pesos hacia delante y arriba, con los brazos estirados.', 'Empuja con el pie derecho y vuelve a la posición inicial bajando los pesos.', 'Repite con el pie izquierdo y sigue alternando piernas las repeticiones que quieras.']::text[]),
  ('DhMl549', null, 'Sentadilla completa con barra (vista trasera)', 'glutes', array['hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/DhMl549.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Apoya la barra en la parte alta de la espalda, sobre el trapecio o el deltoides posterior.', 'Aprieta el core y mantén el pecho alto mientras empiezas a bajar.', 'Flexiona rodillas y cadera, llevando la cadera atrás y abajo como si fueras a sentarte.', 'Baja hasta que los muslos queden paralelos al suelo o algo por debajo.']::text[]),
  ('ecl28tP', null, 'Zancada frontal contralateral con mancuerna', 'glutes', array['hamstrings', 'calves']::text[], 'Mancuernas', 'Intermedio', 'catalog/ecl28tP.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano.', 'Da un paso adelante con el pie derecho, con la espalda recta y el core apretado.', 'Baja flexionando las dos rodillas hasta que el muslo derecho quede paralelo al suelo.', 'Empuja con el talón derecho para volver a la posición inicial.', 'Repite con la pierna izquierda.']::text[]),
  ('lFhb2Rw', null, 'Sentadilla frontal en multipower (agarre de cargada)', 'glutes', array['hamstrings', 'calves']::text[], 'Máquina', 'Avanzado', 'catalog/lFhb2Rw.mp4', array['Coloca la barra del multipower a la altura de los hombros.', 'Ponte de pie frente a la barra con los pies a la anchura de los hombros.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Da un paso atrás y coloca la barra sobre los hombros, apoyada en la clavícula y los deltoides.', 'Mantén el pecho alto, la espalda recta y el core apretado.']::text[]),
  ('u27Kcdz', null, 'Extensión de cadera en banco', 'glutes', array['hamstrings']::text[], 'Peso corporal', 'Principiante', 'catalog/u27Kcdz.mp4', array['Siéntate en un banco con la espalda apoyada y los pies en el suelo.', 'Apoya las manos en el banco para sujetarte.', 'Aprieta glúteos e isquios y despega la cadera del banco hasta quedar en línea recta de las rodillas a los hombros.', 'Aguanta un momento arriba y baja la cadera despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('JZuApnB', null, 'Sentadilla con lastre', 'glutes', array['hamstrings', 'calves']::text[], 'Con lastre', 'Intermedio', 'catalog/JZuApnB.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Sujeta un peso delante del pecho o sobre los hombros.', 'Aprieta el core y mantén el pecho alto mientras bajas la cadera atrás, como si fueras a sentarte.', 'Baja hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.', 'Empuja con los talones para subir, apretando los glúteos arriba.']::text[]),
  ('vR1vold', null, 'Sentadilla Zercher completa con barra', 'glutes', array['hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/vR1vold.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Sujeta la barra en el hueco de los codos, agarrándola con las manos para estabilizarla.', 'Aprieta el core y mantén el pecho alto mientras bajas la cadera atrás hasta la sentadilla.', 'Mantén las rodillas en línea con las puntas de los pies y el peso en los talones.', 'Baja hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.']::text[]),
  ('nUwVh7b', null, 'Peso muerto con mancuernas', 'glutes', array['hamstrings']::text[], 'Mancuernas', 'Avanzado', 'catalog/nUwVh7b.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas hacia delante.', 'Sujeta una mancuerna en cada mano, con las palmas hacia el cuerpo y los brazos estirados hacia abajo.', 'Flexiona cadera y rodillas, bajando las mancuernas hacia el suelo con la espalda recta.', 'Empuja con los talones y estira cadera y rodillas, subiendo las mancuernas a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('NNoHCEA', null, 'Sentadilla completa en multipower', 'glutes', array['hamstrings', 'calves']::text[], 'Máquina', 'Principiante', 'catalog/NNoHCEA.mp4', array['Coloca la barra del multipower a la altura de los hombros.', 'Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Métete bajo la barra y apóyala en la parte alta de la espalda, sobre el trapecio.', 'Agarra la barra con las manos algo más abiertas que los hombros.', 'Saca la barra del soporte y da un paso atrás, con los pies bien plantados.']::text[]),
  ('6sYyrRX', null, 'Giro tumbado con rodillas flexionadas', 'glutes', array['obliques']::text[], 'Peso corporal', 'Intermedio', 'catalog/6sYyrRX.mp4', array['Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.', 'Estira los brazos a los lados, perpendiculares al cuerpo.', 'Con las rodillas juntas, bájalas despacio hacia un lado, intentando tocar el suelo con ellas.', 'Aguanta un momento, aprieta el core y sube las rodillas despacio a la posición inicial.', 'Repite el movimiento hacia el otro lado.']::text[]),
  ('qg2PGl6', null, 'Puente de glúteo con barra y pies en banco', 'glutes', array['hamstrings']::text[], 'Barra', 'Intermedio', 'catalog/qg2PGl6.mp4', array['Empieza sentado en el borde de un banco con la parte alta de la espalda apoyada y los pies en el suelo, a la anchura de la cadera.', 'Coloca una barra sobre la cadera y sujétala firme con las dos manos.', 'Aprieta glúteos y core y empuja con los talones para despegar la cadera del banco, quedando en línea recta de las rodillas a los hombros.', 'Aguanta un momento arriba apretando los glúteos.', 'Baja la cadera despacio a la posición inicial.']::text[]),
  ('6pTkI99', null, 'Arrancada a un brazo con mancuerna', 'glutes', array['hamstrings']::text[], 'Mancuernas', 'Avanzado', 'catalog/6pTkI99.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en una mano, en pronación.', 'Flexiona un poco las rodillas e inclínate desde la cadera, con la espalda recta y el pecho alto.', 'Baja la mancuerna hacia el suelo, manteniéndola pegada al cuerpo.', 'Estira cadera, rodillas y tobillos de forma explosiva, subiendo la mancuerna en línea recta.', 'Cuando la mancuerna llegue a la altura del hombro, gira rápido la mano y remátala arriba, estirando el brazo del todo.']::text[]),
  ('ZuPXtCK', null, 'Sentadilla hack en multipower', 'glutes', array['hamstrings', 'calves']::text[], 'Máquina', 'Principiante', 'catalog/ZuPXtCK.mp4', array['Ajusta la barra del multipower a una altura adecuada para ti.', 'Ponte de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Colócate bajo la barra, apoyándola en la parte alta del trapecio y los hombros.', 'Agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Aprieta el core y mantén el pecho alto al sacar la barra del soporte.']::text[]),
  ('wfotm7S', null, 'Sentadilla con salto en caída', 'glutes', array['hamstrings', 'calves']::text[], 'Peso corporal', 'Intermedio', 'catalog/wfotm7S.mp4', array['Ponte de pie con los pies a la anchura de los hombros.', 'Baja a la sentadilla flexionando las rodillas y llevando la cadera atrás.', 'Salta de forma explosiva, estirando cadera, rodillas y tobillos.', 'En el aire, junta rápido los pies.', 'Cae suave sobre la punta de los pies y baja enseguida a la sentadilla.']::text[]),
  ('5VCj6iH', null, 'Sentadilla hack con barra', 'glutes', array['hamstrings', 'calves']::text[], 'Barra', 'Intermedio', 'catalog/5VCj6iH.mp4', array['Empieza de pie con los pies a la anchura de los hombros y las puntas algo hacia fuera.', 'Sujeta la barra por detrás de las piernas, apoyada en la parte alta de los muslos.', 'Baja flexionando rodillas y cadera, con la espalda recta y el pecho alto.', 'Sigue bajando hasta que los muslos queden paralelos al suelo, o hasta donde llegues cómodo.', 'Aguanta un momento y empuja con los talones para volver a la posición inicial.']::text[]),
  ('S4pwGlc', null, 'Sentadilla pliométrica con mancuernas', 'glutes', array['hamstrings', 'calves']::text[], 'Mancuernas', 'Intermedio', 'catalog/S4pwGlc.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano a los lados.', 'Baja a la sentadilla flexionando las rodillas y llevando la cadera atrás.', 'Al llegar abajo, explota hacia arriba y salta.', 'En el aire, cambia rápido la posición de los pies y cae con el otro pie delante.', 'Baja enseguida a la sentadilla y repite el salto, cambiando otra vez los pies.']::text[]),
  ('2IHEa2T', null, 'Elevación de gemelos en el suelo con barra', 'calves', array['hamstrings']::text[], 'Barra', 'Principiante', 'catalog/2IHEa2T.mp4', array['Deja una barra en el suelo delante de ti.', 'Apoya la punta de los pies sobre la barra, con los talones al aire.', 'Agárrate a algo estable si necesitas equilibrio.', 'Sube los talones todo lo que puedas, elevando el cuerpo con los gemelos.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.']::text[]),
  ('r29jP7S', null, 'Elevación de gemelos sentado con mancuernas', 'calves', array['hamstrings']::text[], 'Mancuernas', 'Principiante', 'catalog/r29jP7S.mp4', array['Siéntate en un banco o una silla con los pies apoyados en el suelo y una mancuerna sobre los muslos.', 'Apoya la punta de los pies en una superficie elevada, como un step o un taco, con los talones al aire.', 'Sujeta la mancuerna para estabilizarte.', 'Sube los talones todo lo que puedas, quedándote sobre la punta de los pies.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.']::text[]),
  ('yl2IYyy', null, 'Elevación de gemelos de pie en polea', 'calves', array['hamstrings', 'glutes']::text[], 'Polea', 'Principiante', 'catalog/yl2IYyy.mp4', array['Ponte de pie frente a una polea con los pies a la anchura de los hombros.', 'Agárrate a las asas de la polea o ponte la tobillera del cable.', 'Despega los talones del suelo estirando los tobillos todo lo que puedas.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('IeDEXTe', null, 'Elevación de gemelos sentado en prensa', 'calves', array['hamstrings', 'glutes']::text[], 'Máquina', 'Principiante', 'catalog/IeDEXTe.mp4', array['Ajusta el asiento de la prensa para que las rodillas queden algo flexionadas con los pies en la plataforma.', 'Siéntate en la máquina con la espalda contra el respaldo y los pies apoyados en la plataforma, a la anchura de los hombros.', 'Apoya la punta de los pies en la plataforma, con los talones fuera del borde.', 'Quita los seguros y empuja la plataforma estirando las rodillas.', 'Con las rodillas estiradas del todo, baja los talones despacio flexionando los gemelos.']::text[]),
  ('uL9CsKm', null, 'Círculos de tobillo', 'calves', '{}', 'Peso corporal', 'Intermedio', 'catalog/uL9CsKm.mp4', array['Siéntate en el suelo con las piernas estiradas por delante.', 'Despega una pierna del suelo y gira el tobillo en círculos.', 'Haz los círculos que quieras en un sentido y cambia al contrario.', 'Repite con la otra pierna.']::text[]),
  ('LmaFNZS', null, 'Elevación de gemelos tipo burro con lastre', 'calves', array['hamstrings', 'glutes']::text[], 'Con lastre', 'Principiante', 'catalog/LmaFNZS.mp4', array['Ponte en una plataforma elevada con la punta de los pies en el borde y los talones al aire.', 'Agárrate a algo estable para sujetarte.', 'Sube los talones todo lo que puedas estirando los tobillos.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('rGwhJ5o', null, 'Elevación de gemelos de pie a una pierna con barra', 'calves', array['hamstrings', 'glutes']::text[], 'Barra', 'Principiante', 'catalog/rGwhJ5o.mp4', array['Ponte de pie con los pies a la anchura de los hombros y apoya la barra en la parte alta de la espalda.', 'Despega los talones del suelo todo lo que puedas, con los gemelos.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('ykUOVze', null, 'Elevación de gemelos de pie en máquina', 'calves', '{}', 'Máquina', 'Principiante', 'catalog/ykUOVze.mp4', array['Ajusta la máquina a tu altura y ponte con los pies a la anchura de los hombros.', 'Mete los hombros bajo las almohadillas y agárrate a las asas para estabilizarte.', 'Sube los talones todo lo que puedas estirando los tobillos.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('bJYHBIN', null, 'Elevación de gemelos de pie sin peso', 'calves', '{}', 'Peso corporal', 'Principiante', 'catalog/bJYHBIN.mp4', array['Ponte de pie con los pies a la anchura de los hombros y las puntas hacia delante.', 'Apoya las manos en una pared o superficie estable para el equilibrio.', 'Sube los talones despacio, quedándote sobre la punta de los pies.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('6HiHHe0', null, 'Elevación de gemelos balanceada con barra', 'calves', array['hamstrings']::text[], 'Barra', 'Principiante', 'catalog/6HiHHe0.mp4', array['Ponte de pie con los pies a la anchura de los hombros y la barra apoyada en la parte alta de la espalda.', 'Despega los talones todo lo que puedas, en equilibrio sobre la punta de los pies.', 'Baja los talones despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('FxhcxUW', null, 'Elevación de gemelos sentado a una pierna (agarre martillo)', 'calves', array['hamstrings', 'glutes']::text[], 'Mancuernas', 'Principiante', 'catalog/FxhcxUW.mp4', array['Siéntate en un banco o una silla con los pies apoyados en el suelo y una mancuerna sobre los muslos.', 'Apoya un pie en una superficie elevada, como un step o un taco, con el talón al aire.', 'Sujeta la mancuerna con agarre martillo: las palmas enfrentadas y los dedos rodeando el mango.', 'Con el core apretado y la espalda recta, sube el talón todo lo que puedas empujando con la punta del pie.', 'Aguanta un momento arriba y baja el talón despacio a la posición inicial.']::text[]),
  ('9GXrTE6', null, 'Elevación de gemelos a una pierna en el suelo (multipower)', 'calves', array['hamstrings', 'glutes']::text[], 'Máquina', 'Principiante', 'catalog/9GXrTE6.mp4', array['Colócate en el suelo bajo la barra del multipower, de espaldas a la máquina.', 'Apoya la punta de los pies en una superficie elevada, como un disco o un taco.', 'Coloca la barra del multipower sobre las piernas, justo encima de los tobillos.', 'Sujeta la barra con las manos para estabilizarla.', 'Despega los talones del suelo estirando los tobillos y elevando el cuerpo.']::text[]),
  ('iPm26QU', null, 'Salto desde cajón con estabilización a una pierna', 'calves', array['hamstrings', 'glutes']::text[], 'Peso corporal', 'Intermedio', 'catalog/iPm26QU.mp4', array['Ponte delante de un cajón o plataforma con los pies a la anchura de los hombros.', 'Flexiona las rodillas y salta al cajón, cayendo suave con un pie encima y el otro fuera del borde.', 'Estabilízate sobre el cajón con ese pie, manteniendo el otro en el aire.', 'Aguanta esa posición unos segundos, apretando los gemelos para mantener el equilibrio.', 'Baja despacio con el pie que tienes en el cajón y vuelve a la posición inicial.']::text[]),
  ('VW88JNd', null, 'Elevación de gemelos sentado a una pierna (palma arriba)', 'calves', array['hamstrings', 'glutes']::text[], 'Mancuernas', 'Principiante', 'catalog/VW88JNd.mp4', array['Siéntate en un banco o una silla con la espalda recta y los pies apoyados en el suelo.', 'Sujeta una mancuerna en una mano y apóyala sobre el muslo, con la palma hacia arriba.', 'Despega una pierna del suelo y estírala hacia delante, con la rodilla algo flexionada.', 'Sube el talón todo lo que puedas empujando con la punta del pie.', 'Aguanta un momento arriba y baja el talón despacio.']::text[]),
  ('ywaNfuh', null, 'Elevación de gemelos invertida en multipower', 'calves', array['hamstrings']::text[], 'Máquina', 'Principiante', 'catalog/ywaNfuh.mp4', array['Ajusta la barra del multipower justo por debajo de los hombros.', 'Ponte frente a la barra con los pies a la anchura de la cadera y las puntas hacia delante.', 'Apoya la punta de los pies en el borde de un step o plataforma, con los talones al aire.', 'Agárrate a la barra para sujetarte, con la espalda recta y el core apretado.', 'Sube los talones todo lo que puedas, quedándote sobre la punta de los pies.']::text[]),
  ('u5ESqzH', null, 'Elevación de gemelos tipo burro', 'calves', array['hamstrings', 'glutes']::text[], 'Peso corporal', 'Principiante', 'catalog/u5ESqzH.mp4', array['Ponte con las puntas de los pies en una superficie elevada, como un step o un taco.', 'Apoya las manos en algo estable, como una pared o una barandilla, para el equilibrio.', 'Sube los talones todo lo que puedas, quedándote sobre la punta de los pies.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('1kB3Wmk', null, 'Elevación de gemelos a una pierna con mancuerna', 'calves', '{}', 'Mancuernas', 'Principiante', 'catalog/1kB3Wmk.mp4', array['Ponte en el borde de un step o plataforma con los talones al aire y las puntas apoyadas.', 'Sujeta una mancuerna en una mano y apoya la otra en una pared o barandilla.', 'Sube el talón todo lo que puedas, quedándote de puntillas.', 'Aguanta un momento arriba y baja el talón despacio por debajo del step.', 'Repite las repeticiones que quieras y cambia de pierna.']::text[]),
  ('0S75mYG', null, 'Elevación de gemelos sentado a una pierna en multipower', 'calves', array['hamstrings']::text[], 'Máquina', 'Principiante', 'catalog/0S75mYG.mp4', array['Siéntate en la máquina con la espalda contra el respaldo y los pies en el reposapiés.', 'Apoya una pierna en el reposapiés y deja la otra fuera.', 'Con el gemelo, sube el talón todo lo que puedas.', 'Aguanta un momento arriba y baja el talón despacio a la posición inicial.', 'Repite las repeticiones que quieras y cambia de pierna.']::text[]),
  ('dPmaUaU', null, 'Elevación de gemelos de pie con mancuernas', 'calves', '{}', 'Mancuernas', 'Principiante', 'catalog/dPmaUaU.mp4', array['Ponte de pie con los pies a la anchura de los hombros y una mancuerna en cada mano.', 'Despega los talones del suelo todo lo que puedas, con los gemelos.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('6MaEjVA', null, 'Elevación de gemelos de pie en multipower', 'calves', array['hamstrings', 'glutes']::text[], 'Máquina', 'Principiante', 'catalog/6MaEjVA.mp4', array['Ajusta la barra del multipower a una altura que te permita estar de pie con los pies apoyados y los hombros bajo la barra.', 'Colócate bajo la barra con los pies a la anchura de los hombros y las puntas hacia delante.', 'Apoya las manos en la barra para estabilizarte.', 'Aprieta los gemelos y sube los talones despacio, quedándote de puntillas.', 'Aguanta un momento arriba y baja los talones despacio a la posición inicial.']::text[]),
  ('0jp9Rlz', null, 'Elevación de gemelos a una pierna en el suelo', 'calves', '{}', 'Peso corporal', 'Principiante', 'catalog/0jp9Rlz.mp4', array['Ponte de pie con los pies a la anchura de la cadera y apoya las manos en una pared o algo resistente.', 'Despega un pie del suelo y mantén el equilibrio sobre el otro.', 'Sube el talón despacio, quedándote sobre la punta del pie.', 'Aguanta un momento arriba y baja el talón despacio a la posición inicial.', 'Repite las repeticiones que quieras y cambia de pierna.']::text[]),
  ('yzYH9pI', null, 'Curl de muñeca en banco con barra (palmas abajo)', 'forearm', array['biceps']::text[], 'Barra', 'Principiante', 'catalog/yzYH9pI.mp4', array['Siéntate en un banco con los pies apoyados en el suelo y los antebrazos sobre los muslos, palmas hacia abajo.', 'Sujeta la barra en pronación, con las manos a la anchura de los hombros.', 'Baja la barra hacia el suelo flexionando las muñecas, con los antebrazos quietos.', 'Aguanta un momento abajo y sube la barra despacio estirando las muñecas.', 'Repite las repeticiones que quieras.']::text[]),
  ('mtXengz', null, 'Curl de dedos con mancuernas', 'forearm', '{}', 'Mancuernas', 'Principiante', 'catalog/mtXengz.mp4', array['Siéntate en un banco o una silla con los pies apoyados en el suelo y la espalda recta.', 'Sujeta una mancuerna en una mano en supinación, con el antebrazo sobre el muslo y la palma hacia arriba.', 'Deja que la mancuerna ruede hasta la punta de los dedos y súbela cerrando la mano.', 'Repite las repeticiones que quieras y cambia de mano.']::text[]),
  ('eYmsEPR', null, 'Curl de muñeca inverso en polea', 'forearm', '{}', 'Polea', 'Principiante', 'catalog/eYmsEPR.mp4', array['Engancha un cable a la polea baja y siéntate en un banco mirando a la máquina.', 'Agarra el asa en pronación, con las palmas hacia abajo.', 'Apoya los antebrazos en los muslos, con las muñecas fuera del borde.', 'Con los antebrazos quietos, suelta el aire y sube las muñecas todo lo que puedas.', 'Aguanta un momento arriba, coge aire y baja las muñecas despacio a la posición inicial.']::text[]),
  ('B6dAO1t', null, 'Curl de muñeca sentado en multipower', 'forearm', array['biceps']::text[], 'Máquina', 'Principiante', 'catalog/B6dAO1t.mp4', array['Siéntate en un banco delante del multipower con los pies apoyados en el suelo.', 'Agarra la barra en supinación, con las manos a la anchura de los hombros.', 'Apoya los antebrazos en los muslos, dejando las muñecas al aire.', 'Sube las muñecas despacio, llevando la barra hacia los antebrazos.', 'Aguanta un momento arriba y baja la barra despacio a la posición inicial.']::text[]),
  ('arvaszz', null, 'Flexiones bajando a los antebrazos', 'forearm', array['triceps']::text[], 'Peso corporal', 'Intermedio', 'catalog/arvaszz.mp4', array['Ponte en posición de flexión con las manos justo debajo de los hombros y el cuerpo en línea recta.', 'Baja el cuerpo hacia el suelo flexionando los codos, pegados al cuerpo.', 'Con los codos a 90 grados, baja los antebrazos al suelo, manteniendo los codos bajo los hombros.', 'Aguanta un momento y empuja con las palmas para volver a subir a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('bjqbauy', null, 'Apretón de mano de pie con lastre', 'forearm', array['biceps', 'triceps']::text[], 'Con lastre', 'Intermedio', 'catalog/bjqbauy.mp4', array['Ponte de pie con los pies a la anchura de los hombros y un peso en cada mano.', 'Estira los brazos por delante, con las palmas enfrentadas.', 'Aprieta las manos todo lo que puedas, activando los antebrazos.', 'Aguanta el apretón unos segundos y suelta.', 'Repite las repeticiones que quieras.']::text[]),
  ('SJAA2IQ', null, 'Curl de muñeca en banco con barra (palmas arriba)', 'forearm', array['biceps']::text[], 'Barra', 'Principiante', 'catalog/SJAA2IQ.mp4', array['Siéntate en un banco con los pies apoyados en el suelo y sujeta la barra en supinación, con las palmas hacia arriba.', 'Apoya los antebrazos en el banco, dejando las muñecas fuera del borde.', 'Con los antebrazos quietos, suelta el aire y sube las muñecas todo lo que puedas.', 'Aguanta un instante en la contracción, coge aire y baja la barra despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('mym4hJo', null, 'Pronación tumbado con mancuerna', 'forearm', array['biceps']::text[], 'Mancuernas', 'Intermedio', 'catalog/mym4hJo.mp4', array['Túmbate boca abajo en un banco con los brazos estirados hacia abajo y una mancuerna en cada mano.', 'Gira las palmas para que miren hacia arriba.', 'Con los brazos quietos, suelta el aire y sube las mancuernas girando las palmas hacia abajo.', 'Coge aire y baja las mancuernas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('VhX2JdE', null, 'Curl de muñeca tras espalda de pie en polea', 'forearm', array['biceps']::text[], 'Polea', 'Principiante', 'catalog/VhX2JdE.mp4', array['Ponte de pie frente a una polea con los pies a la anchura de los hombros.', 'Sujeta el asa en pronación, con las palmas hacia abajo.', 'Mantén los brazos estirados y los codos pegados al cuerpo.', 'Sube las muñecas despacio, llevando el asa hacia el cuerpo.', 'Aguanta un momento arriba y baja el agarre de la polea despacio a la posición inicial.']::text[]),
