  ('2zNKRUB', null, 'Círculos de muñeca', 'forearm', '{}', 'Peso corporal', 'Intermedio', 'catalog/2zNKRUB.mp4', array['Estira los brazos por delante.', 'Cierra los puños.', 'Gira las muñecas en círculos, con los brazos quietos.', 'Sigue con los círculos de muñeca las repeticiones que quieras.']::text[]),
