  ('JymLInS', null, 'Encogimientos inclinados con mancuernas', 'trapezius', '{}', 'Mancuernas', 'Principiante', 'catalog/JymLInS.mp4', array['Pon un banco inclinado a 45 grados y siéntate con una mancuerna en cada mano.', 'Apoya los pies en el suelo y deja los brazos colgando, con las palmas hacia el cuerpo.', 'Con los brazos estirados, encoge los hombros hacia las orejas todo lo que puedas.', 'Aguanta un momento la contracción y baja los hombros despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
