  ('FkBIE6a', null, 'Femoral tumbado con mancuerna', 'hamstrings', array['glutes']::text[], 'Mancuernas', 'Intermedio', 'catalog/FkBIE6a.mp4', array['Túmbate boca arriba con las piernas estiradas y una mancuerna apoyada en la parte baja del abdomen.', 'Flexiona las rodillas y lleva la mancuerna hacia los glúteos, con los pies apoyados en el suelo.', 'Aguanta un momento arriba y baja la mancuerna despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('GwYwElT', null, 'Curl femoral inverso autoasistido', 'hamstrings', array['glutes', 'calves']::text[], 'Peso corporal', 'Principiante', 'catalog/GwYwElT.mp4', array['Túmbate boca arriba en una esterilla o un banco, con las piernas estiradas.', 'Pon las manos a los lados o bajo los glúteos para apoyarte.', 'Flexiona las rodillas y despega los pies del suelo, llevando los muslos hacia el pecho.', 'Aguanta un momento arriba y baja las piernas despacio a la posición inicial.', 'Repite las repeticiones que quieras.']::text[]),
  ('SiWCcTN', null, 'Cargada de potencia', 'hamstrings', array['glutes', 'calves']::text[], 'Barra', 'Avanzado', 'catalog/SiWCcTN.mp4', array['Empieza con la barra en el suelo delante de ti y los pies a la anchura de los hombros.', 'Agáchate y agarra la barra en pronación, algo más abierto que la anchura de los hombros.', 'Mantén la espalda recta y el pecho alto mientras despegas la barra del suelo, estirando cadera y rodillas.', 'Cuando la barra llegue a media pierna, tira de ella hacia arriba de forma explosiva, encogiendo los hombros y llevando los codos altos y hacia los lados.', 'Cuando la barra llegue arriba del todo, métete rápido debajo girando los codos y recíbela sobre los hombros en posición de sentadilla frontal.']::text[]),
  ('LNE3wfo', null, 'Deslizamiento a una pierna en plataforma', 'hamstrings', array['glutes']::text[], 'Peso corporal', 'Intermedio', 'catalog/LNE3wfo.mp4', array['Empieza de pie con un pie sobre una plataforma o tabla deslizante.', 'Flexiona un poco la rodilla y desliza ese pie hacia atrás, estirando la pierna.', 'Mantén el core apretado y la postura recta durante todo el movimiento.', 'Vuelve despacio a la posición inicial deslizando el pie de vuelta.', 'Repite el movimiento las repeticiones que quieras y cambia de pierna.']::text[]),
  ('C5jncD2', null, 'Curl femoral a una pierna de pie', 'hamstrings', array['glutes']::text[], 'Peso corporal', 'Principiante', 'catalog/C5jncD2.mp4', array['Ponte de pie con los pies a la anchura de la cadera y las manos en la cintura.', 'Pasa el peso a la pierna izquierda y despega el pie derecho del suelo, flexionando la rodilla.', 'Lleva el talón derecho despacio hacia el glúteo, apretando el isquio.', 'Aguanta un momento arriba y baja el pie derecho despacio a la posición inicial.', 'Repite las repeticiones que quieras y cambia de pierna.']::text[])
